    const email = clerkUser.emailAddresses?.[0]?.emailAddress;
    if (!email) {
      return new NextResponse("Unauthorized - E-posta bulunamadı", { status: 401 });
    }

    const dbUser = await prisma.user.findUnique({
      where: { email },
