"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import toast from "react-hot-toast";
import ConfirmModal from "@/components/ui/ConfirmModal";

export default function DeleteCouponButton({ id }: { id: string }) {
  const router = useRouter();
  const [isOpen, setIsOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDelete = async () => {
    setIsDeleting(true);
    try {
      const res = await fetch(`/api/admin/coupons/${id}`, {
        method: 'DELETE',
      });

      if (!res.ok) {
        const data = await res.json();
        toast.error(data.error || 'Silme işlemi başarısız oldu.');
        return;
      }

      toast.success('Kupon başarıyla silindi.');
      router.refresh();
    } catch (error) {
      toast.error('Bir hata oluştu.');
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(true)}
        disabled={isDeleting}
        className="px-4 py-2 text-sm font-bold rounded-lg bg-red-50 text-red-600 hover:bg-red-100 transition-colors flex items-center gap-1 cursor-pointer disabled:opacity-50"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
        </svg>
        Sil
      </button>

      <ConfirmModal
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        onConfirm={handleDelete}
        title="Kuponu Sil"
        description="Bu kuponu kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz."
        confirmText="Evet, Sil"
        cancelText="Vazgeç"
        variant="danger"
        isLoading={isDeleting}
      />
    </>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import AuditDetailDrawer, { AuditDetailDrawerData } from "./AuditDetailDrawer";

export interface AuditLogDTO {
  id: string;
  adminId: string;
  adminName: string;
  adminEmail?: string | null;
  action: string;
  entityType: string;
  entityId?: string | null;
  entityName?: string | null;
  riskLevel: "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";
  oldValue?: unknown;
  newValue?: unknown;
  ipAddress?: string | null;
  userAgent?: string | null;
  createdAt: string;
}

interface AdminAuditClientProps {
  logs: AuditLogDTO[];
  totalLogs: number;
  todayLogsCount: number;
  criticalLogsCount: number;
  productLogsCount: number;
  orderLogsCount: number;
  userLogsCount: number;
}

const RISK_BADGES = {
  LOW: { label: "Low", bg: "bg-green-100 text-green-800 border-green-200" },
  MEDIUM: { label: "Medium", bg: "bg-amber-100 text-amber-800 border-amber-200" },
  HIGH: { label: "High", bg: "bg-orange-100 text-orange-800 border-orange-200" },
  CRITICAL: { label: "Critical", bg: "bg-red-100 text-red-800 border-red-200 font-black animate-pulse" },
};

export default function AdminAuditClient({
  logs,
  totalLogs,
  todayLogsCount,
  criticalLogsCount,
  productLogsCount,
  orderLogsCount,
  userLogsCount,
}: AdminAuditClientProps) {
  const router = useRouter();
  const searchParams = useSearchParams();

  const [selectedDrawerLog, setSelectedDrawerLog] = useState<AuditDetailDrawerData | null>(null);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [isPending, startTransition] = useTransition();

  const searchQuery = searchParams.get("q") || "";
  const riskFilter = searchParams.get("risk") || "";
  const entityFilter = searchParams.get("entity") || "";
  const pageSize = Number(searchParams.get("limit")) || 10;
  const currentPage = Number(searchParams.get("page")) || 1;

  const [searchInput, setSearchInput] = useState(searchQuery);

  const updateFilters = (newParams: Record<string, string | number | null>) => {
    const params = new URLSearchParams(searchParams.toString());
    Object.entries(newParams).forEach(([key, value]) => {
      if (value === null || value === "") {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    startTransition(() => {
      router.push(`/admin/audit?${params.toString()}`);
    });
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateFilters({ q: searchInput, page: 1 });
  };

  const exportCSV = () => {
    const headers = ["ID", "Tarih", "Admin", "Islem", "Modul", "Risk", "IP"];
    const rows = logs.map((l) => [
      `"${l.id}"`,
      `"${new Date(l.createdAt).toLocaleDateString("tr-TR")}"`,
      `"${l.adminName.replace(/"/g, '""')}"`,
      `"${l.action.replace(/"/g, '""')}"`,
      `"${l.entityType.replace(/"/g, '""')}"`,
      `"${l.riskLevel}"`,
      `"${l.ipAddress || ""}"`,
    ]);

    const csvContent = "\uFEFF" + [headers.join(";"), ...rows.map((r) => r.join(";"))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `audit-log-raporu-${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const openDrawer = (log: AuditLogDTO) => {
    setSelectedDrawerLog(log);
    setIsDrawerOpen(true);
  };

  const totalPages = Math.ceil(logs.length / pageSize) || 1;
  const paginatedLogs = logs.slice((currentPage - 1) * pageSize, currentPage * pageSize);

