                  </div>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                  <span className="font-mono text-[10px] text-gray-400">IP: {log.ipAddress || "127.0.0.1"}</span>
                  <button
                    onClick={() => openDrawer(log)}
                    className="p-1.5 bg-blue-50 text-blue-700 rounded-lg text-xs font-bold min-h-[36px]"
                  >
                    👁 Diff & Detay İncele
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {/* 🚀 PAGINATION SAYFALAMA BARI */}
        {totalPages > 1 && (
          <div className="p-4 bg-gray-50 border-t border-gray-200 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs">
            <span className="text-gray-500 font-medium">
              Sayfa <span className="font-bold text-gray-900">{currentPage}</span> / {totalPages}
            </span>

            <div className="flex items-center gap-1">
              <button
                disabled={currentPage === 1}
                onClick={() => updateFilters({ page: currentPage - 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                &larr; Önceki
              </button>

              {Array.from({ length: totalPages }).map((_, idx) => {
                const pageNum = idx + 1;
                return (
                  <button
                    key={pageNum}
                    onClick={() => updateFilters({ page: pageNum })}
                    className={`w-8 h-8 rounded-lg font-bold transition ${
                      currentPage === pageNum
                        ? "bg-gray-900 text-white"
                        : "bg-white border border-gray-200 text-gray-700 hover:bg-gray-100"
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}

              <button
                disabled={currentPage === totalPages}
                onClick={() => updateFilters({ page: currentPage + 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                Sonraki &rarr;
              </button>
            </div>
          </div>
        )}

      </div>

      {/* 🚀 DETAY KAYAR PANELİ VE CHANGE DIFF VIEWER (DRAWER) */}
      <AuditDetailDrawer
        log={selectedDrawerLog}
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
      />

    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import toast from "react-hot-toast";
import CouponWizardModal from "./CouponWizardModal";
import CouponDetailDrawer, { CouponDetailDrawerData } from "./CouponDetailDrawer";
import DeleteCouponButton from "@/components/admin/DeleteCouponButton";
import ConfirmModal from "@/components/ui/ConfirmModal";

export interface CouponDTO {
  id: string;
  code: string;
  discount: number;
  minAmount?: number | null;
  isSingleUse: boolean;
  usageLimit: number;
  usedCount: number;
  expireDate: string;
  isActive: boolean;
  createdAt: string;
  usages: {
    id: string;
    createdAt: string;
    user: { name: string; email: string };
    order: { id: string; totalPrice: number; status: string };
  }[];
}

interface AdminCouponsClientProps {
  coupons: CouponDTO[];
  totalCoupons: number;
  activeCount: number;
  expiringSoonCount: number;
  passiveCount: number;
  couponRevenue: number;
  usageRate: number;
}

export default function AdminCouponsClient({
  coupons,
  totalCoupons,
  activeCount,
  expiringSoonCount,
  passiveCount,
  couponRevenue,
  usageRate,
}: AdminCouponsClientProps) {
  const router = useRouter();
  const searchParams = useSearchParams();

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isWizardOpen, setIsWizardOpen] = useState(false);
  const [selectedDrawerCoupon, setSelectedDrawerCoupon] = useState<CouponDetailDrawerData | null>(null);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [isBulkDeleteModalOpen, setIsBulkDeleteModalOpen] = useState(false);
  const [isPending, startTransition] = useTransition();

  const searchQuery = searchParams.get("q") || "";
  const statusFilter = searchParams.get("status") || "";
  const pageSize = Number(searchParams.get("limit")) || 10;
  const currentPage = Number(searchParams.get("page")) || 1;

  const [searchInput, setSearchInput] = useState(searchQuery);

  const updateFilters = (newParams: Record<string, string | number | null>) => {
    const params = new URLSearchParams(searchParams.toString());
    Object.entries(newParams).forEach(([key, value]) => {
      if (value === null || value === "") {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    startTransition(() => {
      router.push(`/admin/coupons?${params.toString()}`);
    });
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateFilters({ q: searchInput, page: 1 });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(coupons.map((c) => c.id));
    } else {
      setSelectedIds([]);
    }
  };

  const toggleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleBulkAction = async (action: string) => {
    if (selectedIds.length === 0) return;

    if (action === "delete") {
      setIsBulkDeleteModalOpen(true);
      return;
    }

    await executeBulkAction(action);
  };

  const executeBulkAction = async (action: string) => {
    const toastId = toast.loading(`${selectedIds.length} kupon işleniyor...`);
    try {
      const res = await fetch("/api/admin/coupons/bulk", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ couponIds: selectedIds, action }),
      });

      if (res.ok) {
        toast.success("Toplu işlem başarıyla tamamlandı!", { id: toastId });
        setSelectedIds([]);
        router.refresh();
      } else {
        toast.error("Toplu işlem başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası oluştu.", { id: toastId });
    }
  };

  const handleToggleActive = async (couponId: string) => {
    const toastId = toast.loading("Durum güncelleniyor...");
    try {
      const res = await fetch("/api/admin/coupons/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "toggleActive", couponId }),
      });

      if (res.ok) {
        toast.success("Kupon aktiflik durumu değiştirildi!", { id: toastId });
        router.refresh();
      } else {
        toast.error("İşlem başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  };

  const handleDuplicateCoupon = async (couponId: string) => {
    const toastId = toast.loading("Kupon çoğaltılıyor (kopyalanıyor)...");
    try {
      const res = await fetch("/api/admin/coupons/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "duplicateCoupon", couponId }),
      });

      if (res.ok) {
        toast.success("Kupon başarıyla kopyalandı!", { id: toastId });
        router.refresh();
      } else {
        toast.error("Kopyalama başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  };

  const openDrawer = (coupon: CouponDTO) => {
    setSelectedDrawerCoupon(coupon);
    setIsDrawerOpen(true);
  };

  const totalPages = Math.ceil(coupons.length / pageSize) || 1;
  const paginatedCoupons = coupons.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return (
    <div className="space-y-6 w-full overflow-x-clip animate-in fade-in duration-300">

      {/* 🚀 BAŞLIK VE AKSİYONLAR */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-200 pb-5">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
            <span>🎟️</span> Kampanya & Kupon Yönetim Merkezi
          </h1>
          <p className="text-gray-500 text-xs sm:text-sm mt-0.5 font-medium">
            Shopify ve Marketing standartlarında indirim kuponları ve kampanya yönetimi.
          </p>
        </div>

        <div className="flex items-center gap-2">
          {selectedIds.length > 0 && (
            <div className="flex items-center gap-2 bg-blue-50 border border-blue-200 p-2 rounded-2xl shadow-xs animate-in zoom-in duration-200">
              <span className="text-xs font-black text-blue-900 px-2">{selectedIds.length} Seçildi:</span>
              <button
                onClick={() => handleBulkAction("activate")}
                className="bg-green-600 hover:bg-green-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs min-h-[36px]"
              >
                🟢 Aktifleştir
              </button>
              <button
                onClick={() => handleBulkAction("deactivate")}
                className="bg-amber-600 hover:bg-amber-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs min-h-[36px]"
              >
                🔴 Pasifleştir
              </button>
              <button
                onClick={() => handleBulkAction("delete")}
                className="bg-red-600 hover:bg-red-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs min-h-[36px]"
              >
                🗑 Sil
              </button>
            </div>
          )}

          <button
            onClick={() => setIsWizardOpen(true)}
            className="bg-blue-600 hover:bg-blue-700 text-white font-extrabold px-4 py-2.5 rounded-xl text-xs sm:text-sm transition shadow-sm min-h-[44px] flex items-center gap-1.5"
          >
            <span>➕</span> Yeni Kampanya Sihirbazı
          </button>
        </div>
      </div>

      {/* 🚀 1. ÖZET İSTATİSTİK 6 METRİK KARTI */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 sm:gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-blue-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Toplam Kupon</span>
          <p className="text-xl sm:text-2xl font-black text-gray-900">{totalCoupons}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-green-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Aktif Kampanya</span>
          <p className="text-xl sm:text-2xl font-black text-green-600">{activeCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-amber-500">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Yakında Bitecek</span>
          <p className="text-xl sm:text-2xl font-black text-amber-600">{expiringSoonCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-red-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Pasif / Süresi Dolan</span>
          <p className="text-xl sm:text-2xl font-black text-red-600">{passiveCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-emerald-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Kuponlu Satış</span>
          <p className="text-xl sm:text-2xl font-black text-emerald-600">{couponRevenue.toLocaleString("tr-TR")} ₺</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-purple-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Kullanım Oranı</span>
          <p className="text-xl sm:text-2xl font-black text-purple-600">%{usageRate}</p>
        </div>
      </div>

      {/* 🚀 2. GELİŞMİŞ FİLTRELEME BAR */}
      <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 space-y-3">
        <form onSubmit={handleSearchSubmit} className="flex flex-col lg:flex-row gap-3 items-stretch lg:items-center">

          {/* Global Arama Kutu */}
          <div className="flex-1 relative">
            <span className="absolute left-3.5 top-3 text-gray-400 text-sm">🔍</span>
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="Kupon Kodu (Örn: YAZ100) arayın..."
              className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-xs sm:text-sm min-h-[44px] uppercase"
            />
          </div>

          {/* Durum Filtresi */}
          <select
            value={statusFilter}
            onChange={(e) => updateFilters({ status: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Kampanya Durumları</option>
            <option value="active">🟢 Aktif Kampanyalar</option>
            <option value="passive">🔴 Pasif / Süresi Dolanlar</option>
          </select>

          <button
            type="submit"
            className="bg-gray-900 hover:bg-gray-800 text-white font-extrabold px-5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
          >
            Filtrele
          </button>

          {(searchQuery || statusFilter) && (
            <button
              type="button"
              onClick={() => {
                setSearchInput("");
                startTransition(() => router.push("/admin/coupons"));
              }}
              className="text-red-600 hover:bg-red-50 border border-red-200 font-extrabold px-3.5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
            >
              Filtreleri Sıfırla
            </button>
          )}
        </form>
      </div>

      {/* 🚀 3. MODERN DATA TABLE (DESKTOP) VE KART DÜZENİ (MOBİL 320px - 430px) */}
      <div className="bg-white rounded-2xl shadow-xs border border-gray-200 overflow-hidden">

        {/* ÜST TOPLU SEÇİM VE GÖSTERİM BARI */}
        <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
          <label className="flex items-center gap-2 text-xs font-bold text-gray-700 cursor-pointer">
            <input
              type="checkbox"
              checked={selectedIds.length === coupons.length && coupons.length > 0}
              onChange={handleSelectAll}
              className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
            />
            Tümünü Seç ({coupons.length} Kupon)
          </label>

          <div className="flex items-center gap-2 text-xs text-gray-500">
            <span>Sayfa Başı Gösterim:</span>
            <select
              value={pageSize}
              onChange={(e) => updateFilters({ limit: Number(e.target.value), page: 1 })}
              className="bg-white border border-gray-200 px-2 py-1 rounded-lg text-xs font-bold outline-none"
            >
              <option value={10}>10</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
            </select>
          </div>
        </div>

        {/* 💻 MASAÜSTÜ VERİ TABLOSU (hidden md:block) */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left text-xs sm:text-sm">
            <thead className="bg-gray-50 text-gray-500 font-extrabold uppercase tracking-wider text-[10px] border-b border-gray-200">
              <tr>
                <th className="p-3.5 w-10 text-center">#</th>
                <th className="p-3.5">Kupon Kodu</th>
                <th className="p-3.5">İndirim Oranı</th>
                <th className="p-3.5">Min. Sepet</th>
                <th className="p-3.5">Kullanım</th>
                <th className="p-3.5">Son Kullanma</th>
                <th className="p-3.5">Durum</th>
                <th className="p-3.5 text-center">İşlemler</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 font-medium">
              {paginatedCoupons.map((coupon) => {
                const isSelected = selectedIds.includes(coupon.id);
                const isExpired = new Date(coupon.expireDate) < new Date();

                return (
                  <tr
                    key={coupon.id}
                    className={`transition ${isSelected ? "bg-blue-50/40" : "hover:bg-gray-50/70"}`}
                  >
                    <td className="p-3.5 text-center">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelectOne(coupon.id)}
                        className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                      />
                    </td>

                    <td className="p-3.5">
                      <div className="flex items-center gap-2">
                        <span className="font-mono font-black text-gray-900 text-sm tracking-wider uppercase">
                          {coupon.code}
                        </span>
                        {coupon.isSingleUse && (
                          <span className="bg-blue-100 text-blue-800 text-[9px] font-black px-2 py-0.5 rounded uppercase">
                            Tek Kullanım
                          </span>
                        )}
                      </div>
                    </td>

                    <td className="p-3.5 font-black text-emerald-600">
                      %{coupon.discount}
                    </td>

                    <td className="p-3.5 font-bold text-gray-800">
                      {coupon.minAmount ? `${coupon.minAmount.toLocaleString("tr-TR")} ₺` : "Limit Yok"}
                    </td>

                    <td className="p-3.5 font-bold text-gray-700">
                      {coupon.usedCount} / {coupon.usageLimit}
                    </td>

                    <td className="p-3.5 text-gray-600">
                      {new Date(coupon.expireDate).toLocaleDateString("tr-TR")}
                    </td>

                    <td className="p-3.5">
                      <button
                        onClick={() => handleToggleActive(coupon.id)}
                        className={`px-3 py-1 rounded-full text-xs font-bold transition flex items-center gap-1.5 ${
                          coupon.isActive && !isExpired
                            ? "bg-green-100 text-green-800 border border-green-200 hover:bg-green-200"
                            : isExpired
                            ? "bg-red-100 text-red-800 border border-red-200"
                            : "bg-gray-100 text-gray-600 border border-gray-200 hover:bg-gray-200"
                        }`}
                      >
                        <span>{coupon.isActive && !isExpired ? "🟢" : "🔴"}</span>
                        <span>{coupon.isActive && !isExpired ? "Aktif" : isExpired ? "Süresi Doldu" : "Pasif"}</span>
                      </button>
                    </td>

                    <td className="p-3.5 text-center">
                      <div className="flex items-center justify-center gap-1.5">
                        <button
                          onClick={() => openDrawer(coupon)}
                          className="p-1.5 text-gray-500 hover:text-blue-600 bg-gray-100 hover:bg-blue-50 rounded-lg transition min-h-[36px] min-w-[36px] flex items-center justify-center font-bold text-xs"
                          title="Hızlı Yan Panel Detayı Aç"
                        >
                          👁️
                        </button>

                        <button
                          onClick={() => handleDuplicateCoupon(coupon.id)}
                          className="p-1.5 text-gray-500 hover:text-purple-600 bg-gray-100 hover:bg-purple-50 rounded-lg transition min-h-[36px] min-w-[36px] flex items-center justify-center font-bold text-xs"
                          title="Kuponu Çoğalt (Duplicate)"
                        >
                          📄
                        </button>

                        <DeleteCouponButton id={coupon.id} />
                      </div>
                    </td>
                  </tr>
                );
              })}

              {paginatedCoupons.length === 0 && (
                <tr>
                  <td colSpan={8} className="p-12 text-center text-gray-400 font-medium">
                    <div className="flex flex-col items-center justify-center space-y-2">
                      <span className="text-4xl">🎟️</span>
                      <p className="text-base font-extrabold text-gray-700">Kupon Bulunamadı</p>
                      <p className="text-xs text-gray-500">Seçtiğiniz filtreye uygun kampanya veya kupon yok.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* 📱 MOBİL KART GÖRÜNÜMÜ (320px - 430px ZORUNLU KONTROL) */}
        <div className="md:hidden divide-y divide-gray-100">
          {paginatedCoupons.map((coupon) => {
            const isSelected = selectedIds.includes(coupon.id);
            const isExpired = new Date(coupon.expireDate) < new Date();

            return (
              <div key={coupon.id} className={`p-4 space-y-3 ${isSelected ? "bg-blue-50/40" : ""}`}>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => toggleSelectOne(coupon.id)}
                      className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                    />
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono font-black text-gray-900 text-sm tracking-wider uppercase">
                          {coupon.code}
                        </span>
                        {coupon.isSingleUse && (
                          <span className="bg-blue-100 text-blue-800 text-[9px] font-black px-1.5 py-0.5 rounded">
                            Tek
                          </span>
                        )}
                      </div>
                      <p className="text-[11px] text-gray-500 font-medium mt-0.5">
                        Son Tarih: {new Date(coupon.expireDate).toLocaleDateString("tr-TR")}
                      </p>
                    </div>
                  </div>

                  <span className={`text-[10px] font-black px-2.5 py-0.5 rounded-full ${
                    coupon.isActive && !isExpired ? "bg-green-100 text-green-800" : "bg-red-100 text-red-800"
                  }`}>
                    {coupon.isActive && !isExpired ? "🟢 Aktif" : "🔴 Pasif"}
                  </span>
                </div>

                <div className="flex justify-between items-center bg-gray-50 p-2.5 rounded-xl text-xs">
                  <div>
                    <span className="text-[10px] text-gray-400 block font-bold">İNDİRİM</span>
                    <span className="font-black text-emerald-600">%{coupon.discount}</span>
                  </div>
                  <div>
                    <span className="text-[10px] text-gray-400 block font-bold">KULLANIM</span>
                    <span className="font-extrabold text-gray-800">{coupon.usedCount} / {coupon.usageLimit}</span>
                  </div>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                  <button
                    onClick={() => handleToggleActive(coupon.id)}
                    className="p-1.5 bg-gray-100 text-gray-700 rounded-lg text-xs font-bold min-h-[36px]"
                  >
                    {coupon.isActive ? "Pasife Al" : "Aktifleştir"}
                  </button>

                  <div className="flex items-center gap-1.5">
                    <button
                      onClick={() => openDrawer(coupon)}
                      className="p-1.5 bg-blue-50 text-blue-700 rounded-lg text-xs font-bold min-h-[36px]"
                    >
                      👁 Detay
                    </button>
                    <button
                      onClick={() => handleDuplicateCoupon(coupon.id)}
                      className="p-1.5 bg-purple-50 text-purple-700 rounded-lg text-xs font-bold min-h-[36px]"
                    >
                      📄 Çoğalt
                    </button>
                    <DeleteCouponButton id={coupon.id} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* 🚀 PAGINATION SAYFALAMA BARI */}
        {totalPages > 1 && (
          <div className="p-4 bg-gray-50 border-t border-gray-200 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs">
            <span className="text-gray-500 font-medium">
              Sayfa <span className="font-bold text-gray-900">{currentPage}</span> / {totalPages}
            </span>

            <div className="flex items-center gap-1">
              <button
                disabled={currentPage === 1}
                onClick={() => updateFilters({ page: currentPage - 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                &larr; Önceki
              </button>

              {Array.from({ length: totalPages }).map((_, idx) => {
                const pageNum = idx + 1;
                return (
                  <button
                    key={pageNum}
                    onClick={() => updateFilters({ page: pageNum })}
                    className={`w-8 h-8 rounded-lg font-bold transition ${
                      currentPage === pageNum
                        ? "bg-gray-900 text-white"
                        : "bg-white border border-gray-200 text-gray-700 hover:bg-gray-100"
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}

              <button
                disabled={currentPage === totalPages}
                onClick={() => updateFilters({ page: currentPage + 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                Sonraki &rarr;
              </button>
            </div>
          </div>
        )}

      </div>

      {/* 🚀 5 STEPPER KAMPANYA SİHİRBAZI MODALI */}
      <CouponWizardModal
        isOpen={isWizardOpen}
        onClose={() => setIsWizardOpen(false)}
        onSuccess={() => router.refresh()}
      />

      {/* 🚀 KUPON HIZLI DETAY KAYAR PANELİ (DRAWER) */}
      <CouponDetailDrawer
        coupon={selectedDrawerCoupon}
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
      />

      {/* Toplu Kupon Silme Onay Modalı */}
      <ConfirmModal
        isOpen={isBulkDeleteModalOpen}
        onClose={() => setIsBulkDeleteModalOpen(false)}
        onConfirm={() => executeBulkAction("delete")}
        title="Toplu Kupon Silme"
        description={`Seçilen ${selectedIds.length} kuponu kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`}
        confirmText="Evet, Toplu Sil"
        cancelText="Vazgeç"
        variant="danger"
      />

    </div>
  );
}

"use client";

import { useEffect } from "react";
import Link from "next/link";

export interface CouponDetailDrawerData {
  id: string;
  code: string;
  discount: number;
  minAmount?: number | null;
  isSingleUse: boolean;
  usageLimit: number;
  usedCount: number;
  expireDate: string;
  isActive: boolean;
  createdAt: string;
  usages: {
    id: string;
    createdAt: string;
    user: { name: string; email: string };
    order: { id: string; totalPrice: number; status: string };
  }[];
}

interface CouponDetailDrawerProps {
  coupon: CouponDetailDrawerData | null;
  isOpen: boolean;
  onClose: () => void;
}

export default function CouponDetailDrawer({ coupon, isOpen, onClose }: CouponDetailDrawerProps) {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    if (isOpen) {
      document.addEventListener("keydown", handleKeyDown);
    }
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen || !coupon) return null;

  const isExpired = new Date(coupon.expireDate) < new Date();
  const usagePercentage = Math.min(100, Math.round((coupon.usedCount / coupon.usageLimit) * 100));
  const estimatedRevenue = coupon.usages.reduce((sum, u) => sum + (u.order?.totalPrice || 0), 0);

  return (
    <div className="fixed inset-0 z-50 overflow-hidden text-left">
      {/* MOBİL VE MASAÜSTÜ ARKA PLAN BACKDROP OVERLAY */}
      <div
        onClick={onClose}
        className="fixed inset-0 bg-black/50 backdrop-blur-xs transition-opacity duration-300 animate-in fade-in"
      />

      <div className="fixed inset-y-0 right-0 max-w-full flex pl-10 pointer-events-none">
        {/* 🚀 KAYAR KUPON DRAWER PANELİ (DESKTOP SAĞ, MOBİL TAM GENİŞLİK / BOTTOM SHEET) */}
        <div className="w-screen max-w-md md:max-w-lg bg-white shadow-2xl border-l border-gray-200 pointer-events-auto flex flex-col justify-between rounded-l-3xl animate-in slide-in-from-right duration-300">

          {/* DRAWER HEADER */}
          <div className="p-5 sm:p-6 border-b border-gray-100 bg-gray-50/80 flex items-center justify-between rounded-tl-3xl">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-amber-500 text-white font-black text-xl flex items-center justify-center shadow-md">
                🎟️
              </div>

              <div>
                <div className="flex items-center gap-2">
                  <h3 className="font-mono font-black text-gray-900 text-lg uppercase tracking-wider">{coupon.code}</h3>
                  <span className={`text-[10px] font-black px-2.5 py-0.5 rounded-full ${
                    coupon.isActive && !isExpired ? "bg-green-100 text-green-800" : "bg-red-100 text-red-800"
                  }`}>
                    {coupon.isActive && !isExpired ? "🟢 Aktif" : isExpired ? "🔴 Süresi Doldu" : "🔴 Pasif"}
                  </span>
                </div>
                <p className="text-gray-500 text-xs mt-0.5 font-medium">Kampanya Detay & Kullanım Analizi</p>
              </div>
            </div>

            <button
              onClick={onClose}
              className="w-8 h-8 rounded-full bg-gray-200/70 hover:bg-gray-300 text-gray-600 flex items-center justify-center font-bold text-xs transition"
            >
              ✕
            </button>
          </div>

          {/* DRAWER İÇERİK LİSTESİ */}
          <div className="p-5 sm:p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">

            {/* KULLANIM VE PERFORMANS KARTLARI */}
            <div className="grid grid-cols-2 gap-3">
              <div className="bg-emerald-50/60 border border-emerald-100 p-3.5 rounded-2xl">
                <span className="text-[10px] font-extrabold text-emerald-600 uppercase tracking-wider block">Kuponla Sağlanan Ciro</span>
                <p className="text-xl font-black text-emerald-900 mt-0.5">{estimatedRevenue.toLocaleString("tr-TR")} ₺</p>
              </div>

              <div className="bg-blue-50/60 border border-blue-100 p-3.5 rounded-2xl">
                <span className="text-[10px] font-extrabold text-blue-600 uppercase tracking-wider block">Kullanım Adedi</span>
                <p className="text-xl font-black text-blue-900 mt-0.5">{coupon.usedCount} / {coupon.usageLimit}</p>
              </div>
            </div>

            {/* KULLANIM PROGRES BARI */}
            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-200 space-y-2">
              <div className="flex justify-between text-xs font-bold text-gray-700">
                <span>Kupon Doluluk Oranı</span>
                <span>%{usagePercentage} Doldu</span>
              </div>
              <div className="w-full bg-gray-200 h-3 rounded-full overflow-hidden">
                <div
                  style={{ width: `${usagePercentage}%` }}
                  className="bg-blue-600 h-full rounded-full transition-all duration-500"
                />
              </div>
            </div>

            {/* KUPON KURALLARI ÖZETİ */}
            <div className="space-y-2.5 bg-gray-50 p-4 rounded-2xl border border-gray-200 text-xs">
              <div className="flex justify-between items-center">
                <span className="text-gray-500 font-bold">İndirim Miktarı:</span>
                <span className="font-extrabold text-emerald-600 text-sm">%{coupon.discount}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-500 font-bold">Minimum Sepet Tutarı:</span>
                <span className="font-bold text-gray-900">
                  {coupon.minAmount ? `${coupon.minAmount.toLocaleString("tr-TR")} ₺` : "Limit Yok"}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-500 font-bold">Kullanıcı Kısıtı:</span>
                <span className="font-bold text-blue-700">
                  {coupon.isSingleUse ? "Kişiye Özel (1 Kullanım)" : "Sınırsız Kullanım"}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-500 font-bold">Son Kullanma Tarihi:</span>
                <span className="font-bold text-gray-900">{new Date(coupon.expireDate).toLocaleString("tr-TR")}</span>
              </div>
            </div>

            {/* KUPONU KULLANAN MÜŞTERİLER VEYA SİPARİŞLER */}
            <div>
              <h4 className="font-extrabold text-gray-900 text-xs uppercase tracking-wider mb-2 flex items-center gap-1.5">
                <span>👥</span> Son Kullanımlar ({coupon.usages.length})
              </h4>
              {coupon.usages.length === 0 ? (
                <p className="text-xs text-gray-400 font-medium">Bu kupon henüz kullanılmamıştır.</p>
              ) : (
                <div className="space-y-2">
                  {coupon.usages.map((u) => (
                    <div key={u.id} className="p-3 bg-white border border-gray-200 rounded-xl text-xs space-y-1 shadow-2xs">
                      <div className="flex justify-between items-center">
                        <span className="font-extrabold text-gray-900">{u.user?.name || "Anonim"}</span>
                        <span className="font-mono text-gray-500 text-[10px]">{new Date(u.createdAt).toLocaleDateString("tr-TR")}</span>
                      </div>
                      <div className="flex justify-between items-center text-gray-600">
                        <span>Sipariş: #{u.order?.id.slice(-8).toUpperCase()}</span>
                        <span className="font-bold text-blue-600">{u.order?.totalPrice.toLocaleString("tr-TR")} ₺</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

          </div>

          {/* DRAWER FOOTER */}
          <div className="p-4 sm:p-5 border-t border-gray-100 bg-gray-50/80 flex items-center justify-between gap-3 rounded-bl-3xl">
            <button
              onClick={onClose}
              className="bg-gray-900 hover:bg-gray-800 text-white font-extrabold px-4 py-2.5 rounded-xl text-xs transition flex-1 text-center min-h-[44px]"
            >
              Kapat
            </button>
          </div>

        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import toast from "react-hot-toast";

interface CouponWizardModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export default function CouponWizardModal({ isOpen, onClose, onSuccess }: CouponWizardModalProps) {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);

  // Form State
  const [code, setCode] = useState("");
  const [campaignType, setCampaignType] = useState("PERCENTAGE");
  const [discount, setDiscount] = useState<number>(10);
  const [minAmount, setMinAmount] = useState<string>("");
  const [usageLimit, setUsageLimit] = useState<number>(100);
  const [isSingleUse, setIsSingleUse] = useState(false);
  const [expireDate, setExpireDate] = useState("");

  if (!isOpen) return null;

  const handleNextStep = () => {
    if (step === 1 && !code.trim()) {
      toast.error("Lütfen bir kupon kodu giriniz.");
      return;
    }
    if (step === 2 && (discount <= 0 || isNaN(discount))) {
      toast.error("Lütfen geçerli bir indirim değeri giriniz.");
      return;
    }
    if (step === 4 && !expireDate) {
      toast.error("Lütfen son kullanma tarihi seçiniz.");
      return;
    }
    setStep((prev) => Math.min(prev + 1, 5));
  };

  const handlePrevStep = () => {
    setStep((prev) => Math.max(prev - 1, 1));
  };

  const handleSubmit = async () => {
    const toastId = toast.loading("Kampanya oluşturuluyor...");
    setLoading(true);

    try {
      const res = await fetch("/api/admin/coupons/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "createCoupon",
          code,
          discount,
          minAmount: minAmount ? Number(minAmount) : null,
          isSingleUse,
          usageLimit,
          expireDate,
        }),
      });

      const data = await res.json();

      if (res.ok) {
        toast.success("Kampanya kuponu başarıyla oluşturuldu! 🎉", { id: toastId });
        onSuccess();
        onClose();
        // Reset Form
        setStep(1);
        setCode("");
      } else {
        toast.error(data.error || "Oluşturma başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası oluştu.", { id: toastId });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs animate-in fade-in duration-200 text-left">
      <div className="bg-white rounded-3xl max-w-2xl w-full shadow-2xl border border-gray-100 p-6 sm:p-8 relative overflow-hidden flex flex-col justify-between max-h-[90vh]">

        {/* MODAL HEADER */}
        <div className="flex justify-between items-center border-b border-gray-100 pb-4 mb-4">
          <div className="flex items-center gap-2">
            <span className="text-xl">🎟️</span>
            <h3 className="text-lg sm:text-xl font-black text-gray-900">Kampanya & Kupon Sihirbazı</h3>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-full bg-gray-100 hover:bg-gray-200 text-gray-600 font-bold text-xs flex items-center justify-center transition"
          >
            ✕
          </button>
        </div>

        {/* STEPPER PROGESS BAR (RESPONSIVE DİKEY / YATAY) */}
        <div className="mb-6 bg-gray-50 p-3 rounded-2xl border border-gray-200/80">
          <div className="flex items-center justify-between text-xs font-bold">
            {[
              { num: 1, label: "Temel" },
              { num: 2, label: "İndirim" },
              { num: 3, label: "Kurallar" },
              { num: 4, label: "Tarihler" },
              { num: 5, label: "Onay" },
            ].map((s) => (
              <div
                key={s.num}
                onClick={() => s.num < step && setStep(s.num)}
                className={`flex items-center gap-1.5 cursor-pointer transition ${
                  step === s.num
                    ? "text-blue-600 font-black scale-105"
                    : s.num < step
                    ? "text-green-600 font-bold"
                    : "text-gray-400"
                }`}
              >
                <span
                  className={`w-6 h-6 rounded-full flex items-center justify-center text-[11px] ${
                    step === s.num
                      ? "bg-blue-600 text-white shadow-xs"
                      : s.num < step
                      ? "bg-green-100 text-green-700"
                      : "bg-gray-200 text-gray-500"
                  }`}
                >
                  {s.num < step ? "✓" : s.num}
                </span>
                <span className="hidden sm:inline">{s.label}</span>
              </div>
            ))}
          </div>
        </div>

        {/* STEPPER STEP CONTENT */}
        <div className="flex-1 overflow-y-auto custom-scrollbar py-2 space-y-4 text-xs sm:text-sm">

          {/* STEP 1: TEMEL BİLGİLER */}
          {step === 1 && (
            <div className="space-y-4 animate-in fade-in duration-200">
              <div>
                <label className="block font-extrabold text-gray-900 mb-1">Kupon Kodu (Büyük Harf)</label>
                <input
                  type="text"
                  value={code}
                  onChange={(e) => setCode(e.target.value.toUpperCase())}
                  placeholder="Örn: YAZ2026 veya VIP100"
                  className="w-full border border-gray-200 rounded-xl p-3 bg-gray-50 focus:bg-white font-mono font-bold text-sm tracking-wider uppercase outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block font-extrabold text-gray-900 mb-2">Kampanya İndirim Türü</label>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { id: "PERCENTAGE", title: "Yüzde İndirimi (%)", desc: "Örn: %15 İndirim" },
                    { id: "FIXED", title: "Sabit Tutar (TL)", desc: "Örn: 100 TL İndirim" },
                    { id: "FREE_SHIPPING", title: "Ücretsiz Kargo", desc: "Kargocreti 0 TL" },
                    { id: "FIRST_ORDER", title: "İlk Sipariş İndirimi", desc: "Yeni Müşterilere Özel" },
                  ].map((t) => (
                    <div
                      key={t.id}
                      onClick={() => setCampaignType(t.id)}
                      className={`p-3 rounded-xl border cursor-pointer transition ${
                        campaignType === t.id
                          ? "bg-blue-50/80 border-blue-500 text-blue-900 font-bold shadow-xs"
                          : "bg-white border-gray-200 text-gray-700 hover:bg-gray-50"
                      }`}
                    >
                      <p className="font-extrabold">{t.title}</p>
                      <p className="text-[10px] text-gray-500 mt-0.5">{t.desc}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* STEP 2: İNDİRİM KURALLARI */}
          {step === 2 && (
            <div className="space-y-4 animate-in fade-in duration-200">
              <div>
                <label className="block font-extrabold text-gray-900 mb-1">
                  {campaignType === "PERCENTAGE" ? "İndirim Oranı (%)" : "İndirim Tutarı (₺)"}
                </label>
                <input
                  type="number"
                  value={discount}
                  onChange={(e) => setDiscount(Number(e.target.value))}
                  min={1}
                  className="w-full border border-gray-200 rounded-xl p-3 bg-gray-50 focus:bg-white font-extrabold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block font-extrabold text-gray-900 mb-1">
                  Minimum Sepet Tutarı (₺) (Opsiyonel)
                </label>
                <input
                  type="number"
                  value={minAmount}
                  onChange={(e) => setMinAmount(e.target.value)}
                  placeholder="Örn: 500 (Boş bırakılırsa limit yok)"
                  className="w-full border border-gray-200 rounded-xl p-3 bg-gray-50 focus:bg-white font-extrabold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
          )}

          {/* STEP 3: KULLANIM KURALLARI */}
          {step === 3 && (
            <div className="space-y-4 animate-in fade-in duration-200">
              <div>
                <label className="block font-extrabold text-gray-900 mb-1">Toplam Kullanım Limiti (Adet)</label>
                <input
                  type="number"
                  value={usageLimit}
                  onChange={(e) => setUsageLimit(Number(e.target.value))}
                  min={1}
                  className="w-full border border-gray-200 rounded-xl p-3 bg-gray-50 focus:bg-white font-extrabold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="flex items-center gap-3 p-3 bg-blue-50/50 rounded-2xl border border-blue-100">
                <input
                  type="checkbox"
                  id="singleUseModal"
                  checked={isSingleUse}
                  onChange={(e) => setIsSingleUse(e.target.checked)}
                  className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                />
                <label htmlFor="singleUseModal" className="font-extrabold text-blue-900 cursor-pointer">
                  Kişiye Özel (Her müşteri sadece 1 kez kullanabilir)
                </label>
              </div>
            </div>
          )}

          {/* STEP 4: GEÇERLİLİK TARİHLERİ */}
          {step === 4 && (
            <div className="space-y-4 animate-in fade-in duration-200">
              <div>
                <label className="block font-extrabold text-gray-900 mb-1">Son Kullanma Tarihi ve Saati</label>
                <input
                  type="datetime-local"
                  value={expireDate}
                  onChange={(e) => setExpireDate(e.target.value)}
                  className="w-full border border-gray-200 rounded-xl p-3 bg-gray-50 focus:bg-white font-extrabold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
          )}

          {/* STEP 5: ÖNİZLEME VE ONAY */}
          {step === 5 && (
            <div className="space-y-4 animate-in fade-in duration-200 bg-gray-50 p-5 rounded-2xl border border-gray-200">
              <h4 className="font-black text-gray-900 text-base border-b border-gray-200 pb-2">Kampanya Özeti</h4>

              <div className="space-y-2 font-medium text-xs">
                <div className="flex justify-between">
                  <span className="text-gray-500">Kupon Kodu:</span>
                  <span className="font-mono font-black text-blue-600 text-sm tracking-wider">{code}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">İndirim Miktarı:</span>
                  <span className="font-extrabold text-emerald-600">
                    {campaignType === "PERCENTAGE" ? `%${discount}` : `${discount} TL`}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Min. Sepet Tutarı:</span>
                  <span className="font-bold text-gray-900">
                    {minAmount ? `${Number(minAmount).toLocaleString("tr-TR")} ₺` : "Limit Yok"}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Kullanım Limiti:</span>
                  <span className="font-bold text-gray-900">{usageLimit} Adet</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Kullanıcı Kısıtı:</span>
                  <span className="font-bold text-blue-800">{isSingleUse ? "Kişiye Özel (1 Hak)" : "Sınırsız Kullanım"}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">Son Kullanma Tarihi:</span>
                  <span className="font-bold text-red-600">{new Date(expireDate).toLocaleString("tr-TR")}</span>
                </div>
              </div>
            </div>
          )}

        </div>

        {/* MODAL FOOTER AKSİYONLARI */}
        <div className="mt-6 border-t border-gray-100 pt-4 flex justify-between gap-3">
          {step > 1 ? (
            <button
              onClick={handlePrevStep}
              className="bg-gray-100 hover:bg-gray-200 text-gray-700 font-extrabold px-5 py-2.5 rounded-xl text-xs sm:text-sm transition min-h-[44px]"
            >
              &larr; Geri
            </button>
          ) : (
            <div />
          )}

          {step < 5 ? (
            <button
              onClick={handleNextStep}
              className="bg-gray-900 hover:bg-gray-800 text-white font-extrabold px-6 py-2.5 rounded-xl text-xs sm:text-sm transition min-h-[44px]"
            >
              Devam Et &rarr;
            </button>
          ) : (
            <button
              disabled={loading}
              onClick={handleSubmit}
              className="bg-blue-600 hover:bg-blue-700 text-white font-extrabold px-6 py-2.5 rounded-xl text-xs sm:text-sm transition shadow-sm min-h-[44px]"
            >
              🚀 Kampanyayı Oluştur ve Yayına Al
            </button>
          )}
        </div>

      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import toast from "react-hot-toast";
import OrderStatusSelect from "@/app/admin/orders/OrderStatusSelect";
import OrderInvoiceModal from "./OrderInvoiceModal";

export interface OrderItemDTO {
  id: string;
  totalPrice: number;
  status: string;
  createdAt: string;
  user?: { name?: string | null; email?: string | null } | null;
  itemsCount: number;
  paymentStatus?: string;
}

interface AdminOrdersClientProps {
  orders: OrderItemDTO[];
  totalOrders: number;
  pendingCount: number;
  shippedCount: number;
  deliveredCount: number;
  cancelledCount: number;
}

export default function AdminOrdersClient({
  orders,
  totalOrders,
  pendingCount,
  shippedCount,
  deliveredCount,
  cancelledCount,
}: AdminOrdersClientProps) {
  const router = useRouter();
  const searchParams = useSearchParams();

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isPending, startTransition] = useTransition();

  // URL Arama & Filtre Parametreleri
  const searchQuery = searchParams.get("q") || "";
  const statusFilter = searchParams.get("status") || "";
  const paymentFilter = searchParams.get("payment") || "";
  const pageSize = Number(searchParams.get("limit")) || 10;
  const currentPage = Number(searchParams.get("page")) || 1;

  const [searchInput, setSearchInput] = useState(searchQuery);

  const updateFilters = (newParams: Record<string, string | number | null>) => {
    const params = new URLSearchParams(searchParams.toString());
    Object.entries(newParams).forEach(([key, value]) => {
      if (value === null || value === "") {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    startTransition(() => {
      router.push(`/admin/orders?${params.toString()}`);
    });
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateFilters({ q: searchInput, page: 1 });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(orders.map((o) => o.id));
    } else {
      setSelectedIds([]);
    }
  };

  const toggleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleBulkStatusUpdate = async (targetStatus: string) => {
    if (selectedIds.length === 0) return;

    const toastId = toast.loading(`${selectedIds.length} sipariş güncelleniyor...`);
    try {
      const res = await fetch("/api/admin/orders/bulk", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ orderIds: selectedIds, status: targetStatus }),
      });

      if (res.ok) {
        toast.success(`${selectedIds.length} sipariş durumu güncellendi!`, { id: toastId });
        setSelectedIds([]);
        router.refresh();
      } else {
        toast.error("Toplu güncelleme başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası oluştu.", { id: toastId });
    }
  };

  const handleExportCSV = () => {
    if (orders.length === 0) {
      toast.error("İndirilecek sipariş bulunamadı.");
      return;
    }

    const headers = ["Siparis ID", "Tarih", "Musteri", "E-Posta", "Urun Sayisi", "Tutar (TL)", "Durum"];
    const rows = orders.map((o) => [
      `"#ORD-${o.id.slice(-8).toUpperCase()}"`,
      `"${new Date(o.createdAt).toLocaleDateString("tr-TR")}"`,
      `"${(o.user?.name || "Müşteri").replace(/"/g, '""')}"`,
      `"${(o.user?.email || "-").replace(/"/g, '""')}"`,
      o.itemsCount,
      o.totalPrice,
      `"${o.status}"`,
    ]);

    const csvContent = "\uFEFF" + [headers.join(";"), ...rows.map((r) => r.join(";"))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `siparisler_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success("Sipariş listesi CSV olarak indirildi!");
  };

  const totalPages = Math.ceil(orders.length / pageSize) || 1;
  const paginatedOrders = orders.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return (
    <div className="space-y-6 w-full animate-in fade-in duration-300">

      {/* 🚀 BAŞLIK VE KISA AÇIKLAMA */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-200 pb-5">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
            <span>📋</span> Sipariş Yönetim Merkezi
          </h1>
          <p className="text-gray-500 text-xs sm:text-sm mt-0.5 font-medium">
            Müşteri siparişlerini anlık filtreleyin, durumlarını güncelleyin ve toplu aksiyonlar alın.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={handleExportCSV}
            className="bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold px-3.5 py-2 rounded-xl text-xs transition shadow-xs flex items-center gap-1.5 cursor-pointer"
          >
            <span>📥</span> CSV Olarak İndir
          </button>

          {/* TOPLU İŞLEM BAR (Seçim yapıldığında belirir) */}
          {selectedIds.length > 0 && (
            <div className="flex items-center gap-2 bg-blue-50 border border-blue-200 p-2 rounded-2xl shadow-xs animate-in zoom-in duration-200">
              <span className="text-xs font-black text-blue-900 px-2">
                {selectedIds.length} Seçildi:
              </span>
              <button
                onClick={() => handleBulkStatusUpdate("PROCESSING")}
                className="bg-indigo-600 hover:bg-indigo-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs cursor-pointer"
              >
                ⚙️ Toplu Hazırlanıyor
              </button>
              <button
                onClick={() => handleBulkStatusUpdate("SHIPPED")}
                className="bg-blue-600 hover:bg-blue-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs cursor-pointer"
              >
                🚚 Toplu Kargoya Ver
              </button>
              <button
                onClick={() => handleBulkStatusUpdate("DELIVERED")}
                className="bg-green-600 hover:bg-green-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs cursor-pointer"
              >
                ✅ Toplu Teslim Edildi
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 🚀 1. ÖZET İSTATİSTİK KARTLARI */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 sm:gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-blue-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Toplam Sipariş</span>
          <p className="text-xl sm:text-2xl font-black text-gray-900">{totalOrders}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-amber-500">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Bekleyen</span>
          <p className="text-xl sm:text-2xl font-black text-amber-600">{pendingCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-indigo-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Kargoda</span>
          <p className="text-xl sm:text-2xl font-black text-indigo-600">{shippedCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-green-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Teslim Edildi</span>
          <p className="text-xl sm:text-2xl font-black text-green-600">{deliveredCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-red-600 col-span-2 sm:col-span-1">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">İptal Edilen</span>
          <p className="text-xl sm:text-2xl font-black text-red-600">{cancelledCount}</p>
        </div>
      </div>

      {/* 🚀 2. GELİŞMİŞ FİLTRELEME VE GLOBAL ARAMA BAR */}
      <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 space-y-3">
        <form onSubmit={handleSearchSubmit} className="flex flex-col lg:flex-row gap-3 items-stretch lg:items-center">

          {/* Global Arama Kutu */}
          <div className="flex-1 relative">
            <span className="absolute left-3.5 top-3 text-gray-400 text-sm">🔍</span>
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="Sipariş kopyala (#ORD-...), Müşteri Adı veya Email arayın..."
              className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-xs sm:text-sm min-h-[44px]"
            />
          </div>

          {/* Durum Filtresi */}
          <select
            value={statusFilter}
            onChange={(e) => updateFilters({ status: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Sipariş Durumları</option>
            <option value="PENDING">⏳ Bekleyen</option>
            <option value="PROCESSING">⚙️ Hazırlanıyor</option>
            <option value="SHIPPED">🚚 Kargoya Verildi</option>
            <option value="DELIVERED">✅ Teslim Edildi</option>
            <option value="CANCELLED">🛑 İptal Edilen</option>
          </select>

          {/* Ödeme Durumu Filtresi */}
          <select
            value={paymentFilter}
            onChange={(e) => updateFilters({ payment: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Ödeme Durumları</option>
            <option value="COMPLETED">💳 Ödendi / Tamamlandı</option>
            <option value="PENDING">⏳ Ödeme Bekliyor</option>
            <option value="REFUNDED">🔄 İade Edildi</option>
          </select>

          <button
            type="submit"
            className="bg-gray-900 hover:bg-gray-800 text-white font-extrabold px-5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
          >
            Filtrele
          </button>

          {(searchQuery || statusFilter || paymentFilter) && (
            <button
              type="button"
              onClick={() => {
                setSearchInput("");
                startTransition(() => router.push("/admin/orders"));
              }}
              className="text-red-600 hover:bg-red-50 border border-red-200 font-extrabold px-3.5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
            >
              Filtreleri Sıfırla
            </button>
          )}
        </form>
      </div>

      {/* 🚀 3. MODERN DATA TABLE (DESKTOP) VE KART DÜZENİ (MOBİL) */}
      <div className="bg-white rounded-2xl shadow-xs border border-gray-200 overflow-hidden">

        {/* ÜST TOPLU SEÇİM BİLGİ BAR */}
        <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
          <label className="flex items-center gap-2 text-xs font-bold text-gray-700 cursor-pointer">
            <input
              type="checkbox"
              checked={selectedIds.length === orders.length && orders.length > 0}
              onChange={handleSelectAll}
              className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
            />
            Tümünü Seç ({orders.length} Sipariş)
          </label>

          <div className="flex items-center gap-2 text-xs text-gray-500">
            <span>Sayfa Başı Gösterim:</span>
            <select
              value={pageSize}
              onChange={(e) => updateFilters({ limit: Number(e.target.value), page: 1 })}
              className="bg-white border border-gray-200 px-2 py-1 rounded-lg text-xs font-bold outline-none"
            >
              <option value={10}>10</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
            </select>
          </div>
        </div>

        {/* 💻 MASAÜSTÜ VERİ TABLOSU (hidden md:block) */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left text-xs sm:text-sm">
            <thead className="bg-gray-50 text-gray-500 font-extrabold uppercase tracking-wider text-[10px] border-b border-gray-200">
