                      </Link>
                    </td>
                  </tr>
                );
              })}

              {paginatedOrders.length === 0 && (
                <tr>
                  <td colSpan={8} className="p-12 text-center text-gray-400 font-medium">
                    <div className="flex flex-col items-center justify-center space-y-2">
                      <span className="text-4xl">📦</span>
                      <p className="text-base font-extrabold text-gray-700">Sipariş Bulunamadı</p>
                      <p className="text-xs text-gray-500">Seçtiğiniz filtreye veya arama kelimesine uygun sipariş yok.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* 📱 MOBİL KART GÖRÜNÜMÜ (md:hidden) */}
        <div className="md:hidden divide-y divide-gray-100">
          {paginatedOrders.map((order) => {
            const customerName = order.user?.name || "Anonim Müşteri";
            const customerEmail = order.user?.email || "N/A";
            const isSelected = selectedIds.includes(order.id);

            return (
              <div
                key={order.id}
                className={`p-4 space-y-3 ${isSelected ? "bg-blue-50/40" : ""}`}
              >
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => toggleSelectOne(order.id)}
                      className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                    />
                    <div>
                      <span className="font-mono font-bold text-gray-900 text-xs">
                        #{order.id.slice(-8).toUpperCase()}
                      </span>
                      <p className="font-extrabold text-gray-900 text-sm mt-0.5">{customerName}</p>
                    </div>
                  </div>

                  <span className="font-black text-blue-600 text-base">
                    {order.totalPrice.toLocaleString("tr-TR")} ₺
                  </span>
                </div>

                <div className="flex justify-between items-center text-xs text-gray-500 pt-1">
                  <span>Tarih: {new Date(order.createdAt).toLocaleDateString("tr-TR")}</span>
                  <span className="font-bold text-gray-700">{order.itemsCount} Parça Ürün</span>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-gray-100 gap-2">
                  <OrderStatusSelect orderId={order.id} currentStatus={order.status} />

                  <div className="flex items-center gap-1.5">
                    <OrderInvoiceModal
                      orderId={order.id}
                      customerName={customerName}
                      customerEmail={customerEmail}
                      totalPrice={order.totalPrice}
                      createdAt={order.createdAt}
                      status={order.status}
                    />
                    <Link
                      href={`/admin/orders/${order.id}`}
                      className="bg-blue-50 hover:bg-blue-100 text-blue-700 font-extrabold px-3 py-1.5 rounded-lg text-xs transition min-h-[36px] flex items-center justify-center"
                    >
                      İncele ↗
                    </Link>
                  </div>
                </div>
              </div>
            );
          })}

          {paginatedOrders.length === 0 && (
            <div className="p-8 text-center text-gray-400 text-xs">
              Sipariş bulunamadı.
            </div>
          )}
        </div>

        {/* 🚀 PAGINATION SAYFALAMA BARI */}
        {totalPages > 1 && (
          <div className="p-4 bg-gray-50 border-t border-gray-200 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs">
            <span className="text-gray-500 font-medium">
              Sayfa <span className="font-bold text-gray-900">{currentPage}</span> / {totalPages}
            </span>

            <div className="flex items-center gap-1">
              <button
                disabled={currentPage === 1}
                onClick={() => updateFilters({ page: currentPage - 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                &larr; Önceki
              </button>

              {Array.from({ length: totalPages }).map((_, idx) => {
                const pageNum = idx + 1;
                return (
                  <button
                    key={pageNum}
                    onClick={() => updateFilters({ page: pageNum })}
                    className={`w-8 h-8 rounded-lg font-bold transition ${
                      currentPage === pageNum
                        ? "bg-gray-900 text-white"
                        : "bg-white border border-gray-200 text-gray-700 hover:bg-gray-100"
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}

              <button
                disabled={currentPage === totalPages}
                onClick={() => updateFilters({ page: currentPage + 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                Sonraki &rarr;
              </button>
            </div>
          </div>
        )}

      </div>

    </div>
  );
}

// components/admin/orders/OrderStatusSelect.tsx
"use client";

import { useRouter } from "next/navigation";
import toast from "react-hot-toast";
import { ALLOWED_STATUS_TRANSITIONS, OrderStatusKey } from "@/lib/constants/order-status";

interface OrderStatusSelectProps {
  orderId: string;
  currentStatus: string;
}

const STATUS_LABELS: Record<string, string> = {
  PENDING: "⏳ Bekliyor",
  PROCESSING: "⚙️ Hazırlanıyor",
  SHIPPED: "🚚 Kargoya Verildi",
  DELIVERED: "✅ Teslim Edildi",
  CANCELLED: "❌ İptal Edildi",
};

export default function OrderStatusSelect({ orderId, currentStatus }: OrderStatusSelectProps) {
  const router = useRouter();

  async function handleStatusChange(e: React.ChangeEvent<HTMLSelectElement>) {
    const newStatus = e.target.value;
    if (newStatus === currentStatus) return;

    const toastId = toast.loading("Durum güncelleniyor...");

    try {
      const res = await fetch(`/api/admin/orders/${orderId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });

      const data = await res.json();

      if (res.ok && data.success) {
        toast.success("Sipariş durumu başarıyla değiştirildi!", { id: toastId });
        router.refresh();
      } else {
        toast.error(data.error || "Güncelleme başarısız oldu.", { id: toastId });
      }
    } catch (_error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  }

  const statusColors: Record<string, string> = {
    PENDING: "bg-orange-50 text-orange-700 border-orange-200",
    PROCESSING: "bg-indigo-50 text-indigo-700 border-indigo-200",
    SHIPPED: "bg-blue-50 text-blue-700 border-blue-200",
    DELIVERED: "bg-green-50 text-green-700 border-green-200",
    CANCELLED: "bg-red-50 text-red-700 border-red-200",
  };

  const currentColorClass = statusColors[currentStatus] || "bg-gray-50 text-gray-700 border-gray-200";

  // Re-use state machine rules: filter to current status + allowed next states
  const allowedNext = ALLOWED_STATUS_TRANSITIONS[currentStatus as OrderStatusKey] || [];
  const validOptionKeys = Array.from(new Set([currentStatus, ...allowedNext]));

  return (
    <select
      value={currentStatus}
      onChange={handleStatusChange}
      className={`px-3 py-1.5 rounded-full text-xs font-bold border outline-none cursor-pointer transition ${currentColorClass}`}
    >
      {validOptionKeys.map((key) => (
        <option key={key} value={key}>
          {STATUS_LABELS[key] || key}
        </option>
      ))}
    </select>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import Image from "next/image";
import { useRouter, useSearchParams } from "next/navigation";
import toast from "react-hot-toast";
import QuickStockUpdate from "./QuickStockUpdate";
import QuickPriceUpdate from "./QuickPriceUpdate";
import DeleteButton from "@/app/admin/products/DeleteButton";
import ConfirmModal from "@/components/ui/ConfirmModal";

export interface CategoryItem {
  id: string;
  name: string;
}

export interface BrandItem {
  id: string;
  name: string;
}

export interface ProductDTO {
  id: string;
  name: string;
  slug: string;
  sku?: string | null;
  price: number;
  comparePrice?: number | null;
  stock: number;
  isActive: boolean;
  imageUrl?: string | null;
  category?: { id: string; name: string } | null;
  brand?: { id: string; name: string } | null;
  createdAt: string;
  variantsCount: number;
}

interface AdminProductsClientProps {
  products: ProductDTO[];
  categories: CategoryItem[];
  brands: BrandItem[];
  totalProducts: number;
  activeCount: number;
  passiveCount: number;
  criticalStockCount: number;
  totalBrands: number;
  totalCategories: number;
}

export default function AdminProductsClient({
  products,
  categories,
  brands,
  totalProducts,
  activeCount,
  passiveCount,
  criticalStockCount,
  totalBrands,
  totalCategories,
}: AdminProductsClientProps) {
  const router = useRouter();
  const searchParams = useSearchParams();

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isPending, startTransition] = useTransition();
  const [isBulkDeleteModalOpen, setIsBulkDeleteModalOpen] = useState(false);

  // URL Arama & Filtre Parametreleri
  const searchQuery = searchParams.get("q") || "";
  const categoryFilter = searchParams.get("category") || "";
  const brandFilter = searchParams.get("brand") || "";
  const statusFilter = searchParams.get("status") || "";
  const stockFilter = searchParams.get("stockStatus") || "";
  const pageSize = Number(searchParams.get("limit")) || 10;
  const currentPage = Number(searchParams.get("page")) || 1;

  const [searchInput, setSearchInput] = useState(searchQuery);

  const updateFilters = (newParams: Record<string, string | number | null>) => {
    const params = new URLSearchParams(searchParams.toString());
    Object.entries(newParams).forEach(([key, value]) => {
      if (value === null || value === "") {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    startTransition(() => {
      router.push(`/admin/products?${params.toString()}`);
    });
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateFilters({ q: searchInput, page: 1 });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(products.map((p) => p.id));
    } else {
      setSelectedIds([]);
    }
  };

  const toggleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleBulkAction = async (action: string, targetId?: string) => {
    if (selectedIds.length === 0) return;

    if (action === "delete") {
      setIsBulkDeleteModalOpen(true);
      return;
    }

    await executeBulkAction(action, targetId);
  };

  const executeBulkAction = async (action: string, targetId?: string) => {
    const toastId = toast.loading(`${selectedIds.length} ürün güncelleniyor...`);
    try {
      const res = await fetch("/api/admin/products/bulk", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ productIds: selectedIds, action, targetId }),
      });

      if (res.ok) {
        toast.success("Toplu işlem başarıyla tamamlandı!", { id: toastId });
        setSelectedIds([]);
        router.refresh();
      } else {
        toast.error("Toplu işlem başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası oluştu.", { id: toastId });
    }
  };

  const handleToggleActive = async (productId: string) => {
    const toastId = toast.loading("Durum değiştiriliyor...");
    try {
      const res = await fetch("/api/admin/products/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "toggleActive", productId }),
      });

      if (res.ok) {
        toast.success("Ürün aktiflik durumu değiştirildi!", { id: toastId });
        router.refresh();
      } else {
        toast.error("Durum değiştirilemedi.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  };

  const handleDuplicateProduct = async (productId: string) => {
    const toastId = toast.loading("Ürün çoğaltılıyor (kopyalanıyor)...");
    try {
      const res = await fetch("/api/admin/products/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "duplicateProduct", productId }),
      });

      if (res.ok) {
        toast.success("Ürün başarıyla kopyalandı!", { id: toastId });
        router.refresh();
      } else {
        toast.error("Ürün çoğaltılamadı.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  };

  const totalPages = Math.ceil(products.length / pageSize) || 1;
  const paginatedProducts = products.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return (
    <div className="space-y-6 w-full animate-in fade-in duration-300">

      {/* 🚀 ÜST BAŞLIK VE AKSİYONLAR */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-200 pb-5">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
            <span>📦</span> Ürün Yönetim Merkezi
          </h1>
          <p className="text-gray-500 text-xs sm:text-sm mt-0.5 font-medium">
            Katalog ürünlerini hızlıca yönetin, stok/fiyat güncelleyin ve ürünleri çoğaltın.
          </p>
        </div>

        <div className="flex items-center gap-2">
          {selectedIds.length > 0 && (
            <div className="flex items-center gap-2 bg-blue-50 border border-blue-200 p-2 rounded-2xl shadow-xs animate-in zoom-in duration-200">
              <span className="text-xs font-black text-blue-900 px-2">{selectedIds.length} Seçildi:</span>
              <button
                onClick={() => handleBulkAction("activate")}
                className="bg-green-600 hover:bg-green-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs"
              >
                🟢 Aktifleştir
              </button>
              <button
                onClick={() => handleBulkAction("deactivate")}
                className="bg-amber-600 hover:bg-amber-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs"
              >
                🔴 Pasifleştir
              </button>
              <button
                onClick={() => handleBulkAction("delete")}
                className="bg-red-600 hover:bg-red-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs"
              >
                🗑 Toplu Sil
              </button>
            </div>
          )}

          <Link
            href="/admin/products/new"
            className="bg-blue-600 hover:bg-blue-700 text-white font-extrabold px-4 py-2.5 rounded-xl text-xs sm:text-sm transition shadow-sm min-h-[44px] flex items-center gap-1.5"
          >
            <span>➕</span> Yeni Ürün Ekle
          </Link>
        </div>
      </div>

      {/* 🚀 1. ÖZET İSTATİSTİK 6 METRİK KARTI */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 sm:gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-blue-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Toplam Ürün</span>
          <p className="text-xl sm:text-2xl font-black text-gray-900">{totalProducts}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-green-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Aktif Ürün</span>
          <p className="text-xl sm:text-2xl font-black text-green-600">{activeCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-gray-400">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Pasif Ürün</span>
          <p className="text-xl sm:text-2xl font-black text-gray-600">{passiveCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-red-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Kritik Stok</span>
          <p className="text-xl sm:text-2xl font-black text-red-600">{criticalStockCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-purple-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Toplam Marka</span>
          <p className="text-xl sm:text-2xl font-black text-purple-600">{totalBrands}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-teal-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Kategori</span>
          <p className="text-xl sm:text-2xl font-black text-teal-600">{totalCategories}</p>
        </div>
      </div>

      {/* 🚀 2. GELİŞMİŞ FİLTRELEME VE GLOBAL ARAMA BAR */}
      <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 space-y-3">
        <form onSubmit={handleSearchSubmit} className="flex flex-col lg:flex-row gap-3 items-stretch lg:items-center">

          {/* Global Arama Kutu */}
          <div className="flex-1 relative">
            <span className="absolute left-3.5 top-3 text-gray-400 text-sm">🔍</span>
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="Ürün Adı, SKU veya Slug arayın..."
              className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-xs sm:text-sm min-h-[44px]"
            />
          </div>

          {/* Kategori Filtresi */}
          <select
            value={categoryFilter}
            onChange={(e) => updateFilters({ category: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Kategoriler</option>
            {categories.map((c) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>

          {/* Marka Filtresi */}
          <select
            value={brandFilter}
            onChange={(e) => updateFilters({ brand: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Markalar</option>
            {brands.map((b) => (
              <option key={b.id} value={b.id}>{b.name}</option>
            ))}
          </select>

          {/* Durum Filtresi */}
          <select
            value={statusFilter}
            onChange={(e) => updateFilters({ status: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Durumlar</option>
            <option value="active">🟢 Aktif Ürünler</option>
            <option value="passive">🔴 Pasif Ürünler</option>
          </select>

          {/* Stok Durumu Filtresi */}
          <select
            value={stockFilter}
            onChange={(e) => updateFilters({ stockStatus: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Stok Seviyeleri</option>
            <option value="in_stock">✅ Stokta Var (&gt;5)</option>
            <option value="critical">⚠️ Kritik Stok (1-5)</option>
            <option value="out_of_stock">🚫 Stok Tükendi (0)</option>
          </select>

          <button
            type="submit"
            className="bg-gray-900 hover:bg-gray-800 text-white font-extrabold px-5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
          >
            Filtrele
          </button>

          {(searchQuery || categoryFilter || brandFilter || statusFilter || stockFilter) && (
            <button
              type="button"
              onClick={() => {
                setSearchInput("");
                startTransition(() => router.push("/admin/products"));
              }}
              className="text-red-600 hover:bg-red-50 border border-red-200 font-extrabold px-3.5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
            >
              Temizle
            </button>
          )}
        </form>
      </div>

      {/* 🚀 3. MODERN DATA TABLE (DESKTOP) VE KART DÜZENİ (MOBİL) */}
      <div className="bg-white rounded-2xl shadow-xs border border-gray-200 overflow-hidden">

        {/* ÜST TOPLU SEÇİM VE GÖSTERİM BARI */}
        <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
          <label className="flex items-center gap-2 text-xs font-bold text-gray-700 cursor-pointer">
            <input
              type="checkbox"
              checked={selectedIds.length === products.length && products.length > 0}
              onChange={handleSelectAll}
              className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
            />
            Tümünü Seç ({products.length} Ürün)
          </label>

          <div className="flex items-center gap-2 text-xs text-gray-500">
            <span>Sayfa Başı Gösterim:</span>
            <select
              value={pageSize}
              onChange={(e) => updateFilters({ limit: Number(e.target.value), page: 1 })}
              className="bg-white border border-gray-200 px-2 py-1 rounded-lg text-xs font-bold outline-none"
            >
              <option value={10}>10</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
            </select>
          </div>
        </div>

        {/* 💻 MASAÜSTÜ VERİ TABLOSU (hidden md:block) */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left text-xs sm:text-sm">
            <thead className="bg-gray-50 text-gray-500 font-extrabold uppercase tracking-wider text-[10px] border-b border-gray-200">
              <tr>
                <th className="p-3.5 w-10 text-center">#</th>
                <th className="p-3.5 w-16">Görsel</th>
                <th className="p-3.5">Ürün Adı & SKU</th>
                <th className="p-3.5">Kategori / Marka</th>
                <th className="p-3.5">Fiyat</th>
                <th className="p-3.5">Stok Düzenle</th>
                <th className="p-3.5">Durum</th>
                <th className="p-3.5 text-right">İşlemler</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 font-medium">
              {paginatedProducts.map((product) => {
                const isSelected = selectedIds.includes(product.id);

                return (
                  <tr
                    key={product.id}
                    className={`transition ${isSelected ? "bg-blue-50/40" : "hover:bg-gray-50/70"}`}
                  >
                    <td className="p-3.5 text-center">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelectOne(product.id)}
                        className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                      />
                    </td>

                    <td className="p-3.5">
                      <div className="w-12 h-12 bg-gray-50 rounded-xl overflow-hidden flex items-center justify-center border border-gray-200 flex-shrink-0">
                        {product.imageUrl ? (
                          <Image src={product.imageUrl} alt={product.name} className="w-full h-full object-contain" width={60} height={60} />
                        ) : (
                          <span className="text-[10px] text-gray-400">Yok</span>
                        )}
                      </div>
                    </td>

                    <td className="p-3.5">
                      <p className="font-extrabold text-gray-900 truncate max-w-xs">{product.name}</p>
                      <p className="text-[11px] text-gray-500 font-mono mt-0.5">
                        {product.sku ? `SKU: ${product.sku}` : "SKU Belirtilmedi"}
                      </p>
                    </td>

                    <td className="p-3.5">
                      <div className="flex flex-col gap-1">
                        <span className="bg-blue-50 text-blue-700 px-2 py-0.5 rounded text-[11px] font-bold w-fit">
                          {product.category?.name || "Kategorisiz"}
                        </span>
                        <span className="bg-purple-50 text-purple-700 px-2 py-0.5 rounded text-[11px] font-bold w-fit">
                          {product.brand?.name || "Markasız"}
                        </span>
                      </div>
                    </td>

                    <td className="p-3.5">
                      <QuickPriceUpdate
                        productId={product.id}
                        currentPrice={product.price}
                        currentComparePrice={product.comparePrice}
                        onUpdate={() => router.refresh()}
                      />
                    </td>

                    <td className="p-3.5">
                      <QuickStockUpdate
                        productId={product.id}
                        currentStock={product.stock}
                        onUpdate={() => router.refresh()}
                      />
                    </td>

                    <td className="p-3.5">
                      <button
                        onClick={() => handleToggleActive(product.id)}
                        className={`px-3 py-1 rounded-full text-xs font-bold transition flex items-center gap-1.5 ${
                          product.isActive
                            ? "bg-green-100 text-green-800 border border-green-200 hover:bg-green-200"
                            : "bg-gray-100 text-gray-600 border border-gray-200 hover:bg-gray-200"
                        }`}
                      >
                        <span>{product.isActive ? "🟢" : "🔴"}</span>
                        <span>{product.isActive ? "Aktif" : "Pasif"}</span>
                      </button>
                    </td>

                    <td className="p-3.5 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <Link
                          href={`/products/${product.id}`}
                          target="_blank"
                          className="p-1.5 text-gray-400 hover:text-blue-600 transition min-h-[36px] min-w-[36px] flex items-center justify-center font-bold text-xs"
                          title="Vitrinde Gör"
                        >
                          👁️
                        </Link>
                        <Link
                          href={`/admin/products/${product.id}/edit`}
                          className="p-1.5 text-gray-400 hover:text-green-600 transition min-h-[36px] min-w-[36px] flex items-center justify-center font-bold text-xs"
                          title="Düzenle"
                        >
                          ✏️
                        </Link>
                        <button
                          onClick={() => handleDuplicateProduct(product.id)}
                          className="p-1.5 text-gray-400 hover:text-purple-600 transition min-h-[36px] min-w-[36px] flex items-center justify-center font-bold text-xs"
                          title="Ürünü Kopyala (Duplicate)"
                        >
                          📄
                        </button>
                        <DeleteButton id={product.id} />
                      </div>
                    </td>
                  </tr>
                );
              })}

              {paginatedProducts.length === 0 && (
                <tr>
                  <td colSpan={8} className="p-12 text-center text-gray-400 font-medium">
                    <div className="flex flex-col items-center justify-center space-y-2">
                      <span className="text-4xl">🔍</span>
                      <p className="text-base font-extrabold text-gray-700">Ürün Bulunamadı</p>
                      <p className="text-xs text-gray-500">Seçtiğiniz filtreye veya arama kelimesine uygun ürün yok.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* 📱 MOBİL KART GÖRÜNÜMÜ (md:hidden) */}
        <div className="md:hidden divide-y divide-gray-100">
          {paginatedProducts.map((product) => {
            const isSelected = selectedIds.includes(product.id);

            return (
              <div key={product.id} className={`p-4 space-y-3 ${isSelected ? "bg-blue-50/40" : ""}`}>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => toggleSelectOne(product.id)}
                      className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                    />
                    <div className="w-12 h-12 bg-gray-50 rounded-xl overflow-hidden border border-gray-200 flex-shrink-0 flex items-center justify-center">
                      {product.imageUrl ? (
                        <Image src={product.imageUrl} alt={product.name} width={50} height={50} className="object-contain" />
                      ) : (
                        <span>📦</span>
                      )}
                    </div>
                    <div>
                      <p className="font-extrabold text-gray-900 text-xs sm:text-sm">{product.name}</p>
                      <p className="text-[11px] text-gray-500 font-mono">SKU: {product.sku || "Yok"}</p>
                    </div>
                  </div>

                  <button
                    onClick={() => handleToggleActive(product.id)}
                    className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold ${
                      product.isActive ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-600"
                    }`}
                  >
                    {product.isActive ? "🟢 Aktif" : "🔴 Pasif"}
                  </button>
                </div>

                <div className="flex justify-between items-center bg-gray-50 p-2.5 rounded-xl text-xs">
                  <div>
                    <span className="text-[10px] text-gray-400 block font-bold">FİYAT</span>
                    <span className="font-extrabold text-gray-900">{product.price.toLocaleString("tr-TR")} ₺</span>
                  </div>
                  <div>
                    <span className="text-[10px] text-gray-400 block font-bold">STOK</span>
                    <QuickStockUpdate
                      productId={product.id}
                      currentStock={product.stock}
                      onUpdate={() => router.refresh()}
                    />
                  </div>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                  <div className="flex gap-1">
                    <span className="bg-blue-50 text-blue-700 px-2 py-0.5 rounded text-[10px] font-bold">
                      {product.category?.name || "Kategorisiz"}
                    </span>
                  </div>

                  <div className="flex items-center gap-1">
                    <Link href={`/admin/products/${product.id}/edit`} className="p-1.5 bg-gray-100 rounded-lg text-xs font-bold">
                      ✏️ Düzenle
                    </Link>
                    <button onClick={() => handleDuplicateProduct(product.id)} className="p-1.5 bg-purple-50 text-purple-700 rounded-lg text-xs font-bold">
                      📄 Çoğalt
                    </button>
                    <DeleteButton id={product.id} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* 🚀 PAGINATION SAYFALAMA BARI */}
        {totalPages > 1 && (
          <div className="p-4 bg-gray-50 border-t border-gray-200 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs">
            <span className="text-gray-500 font-medium">
              Sayfa <span className="font-bold text-gray-900">{currentPage}</span> / {totalPages}
            </span>

            <div className="flex items-center gap-1">
              <button
                disabled={currentPage === 1}
                onClick={() => updateFilters({ page: currentPage - 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                &larr; Önceki
              </button>

              {Array.from({ length: totalPages }).map((_, idx) => {
                const pageNum = idx + 1;
                return (
                  <button
                    key={pageNum}
                    onClick={() => updateFilters({ page: pageNum })}
                    className={`w-8 h-8 rounded-lg font-bold transition ${
                      currentPage === pageNum
                        ? "bg-gray-900 text-white"
                        : "bg-white border border-gray-200 text-gray-700 hover:bg-gray-100"
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}

              <button
                disabled={currentPage === totalPages}
                onClick={() => updateFilters({ page: currentPage + 1 })}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-lg font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:hover:bg-white"
              >
                Sonraki &rarr;
              </button>
            </div>
          </div>
        )}

      </div>

      {/* Toplu Ürün Silme Onay Modalı */}
      <ConfirmModal
        isOpen={isBulkDeleteModalOpen}
        onClose={() => setIsBulkDeleteModalOpen(false)}
        onConfirm={() => executeBulkAction("delete")}
        title="Toplu Ürün Silme"
        description={`Seçilen ${selectedIds.length} ürünü kalıcı olarak silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`}
        confirmText="Evet, Toplu Sil"
        cancelText="Vazgeç"
        variant="danger"
      />

    </div>
  );
}

"use client";

import { useState } from "react";
import toast from "react-hot-toast";

interface QuickPriceUpdateProps {
  productId: string;
  currentPrice: number;
  currentComparePrice?: number | null;
  onUpdate?: () => void;
}

export default function QuickPriceUpdate({
  productId,
  currentPrice,
  currentComparePrice,
  onUpdate,
}: QuickPriceUpdateProps) {
  const [price, setPrice] = useState(currentPrice);
  const [comparePrice, setComparePrice] = useState(currentComparePrice || 0);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleSavePrice = async () => {
    if (price < 0) return;
    const toastId = toast.loading("Fiyat güncelleniyor...");
    setLoading(true);

    try {
      const res = await fetch("/api/admin/products/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "updatePrice",
          productId,
          price,
          comparePrice: comparePrice > 0 ? comparePrice : null,
        }),
      });

      if (res.ok) {
        setIsEditing(false);
        toast.success("Fiyat başarıyla güncellendi!", { id: toastId });
        if (onUpdate) onUpdate();
      } else {
        toast.error("Fiyat güncelleme başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası oluştu.", { id: toastId });
    } finally {
      setLoading(false);
    }
  };

  if (isEditing) {
    return (
      <div className="flex flex-col gap-1 bg-white border border-blue-300 p-2 rounded-xl shadow-sm text-xs animate-in fade-in duration-200">
        <div className="flex items-center gap-1">
          <span className="text-[10px] font-bold text-gray-400">Satış:</span>
          <input
            type="number"
            value={price}
            onChange={(e) => setPrice(Number(e.target.value))}
            className="w-20 font-extrabold border border-gray-200 rounded p-1 outline-none focus:ring-1 focus:ring-blue-500"
          />
          <span>₺</span>
        </div>

        <div className="flex items-center gap-1">
          <span className="text-[10px] font-bold text-gray-400">Eski:</span>
          <input
            type="number"
            value={comparePrice}
            onChange={(e) => setComparePrice(Number(e.target.value))}
            placeholder="0"
            className="w-20 font-medium border border-gray-200 rounded p-1 outline-none focus:ring-1 focus:ring-blue-500 text-gray-500"
          />
          <span>₺</span>
        </div>

        <div className="flex items-center gap-1 mt-1 justify-end">
          <button
            onClick={() => setIsEditing(false)}
            className="px-2 py-0.5 text-gray-500 hover:text-gray-700 font-bold"
          >
            İptal
          </button>
          <button
            disabled={loading}
            onClick={handleSavePrice}
            className="px-2.5 py-1 bg-blue-600 hover:bg-blue-700 text-white font-extrabold rounded-lg transition"
          >
            Kaydet
          </button>
        </div>
      </div>
    );
  }

  const hasDiscount = currentComparePrice && currentComparePrice > currentPrice;

  return (
    <div className="flex items-center gap-1.5 group">
      <div>
        <p className="font-extrabold text-gray-900 text-xs sm:text-sm">
          {price.toLocaleString("tr-TR")} ₺
        </p>
        {hasDiscount && (
          <p className="text-[10px] text-gray-400 line-through">
            {currentComparePrice.toLocaleString("tr-TR")} ₺
          </p>
        )}
      </div>
      <button
        onClick={() => setIsEditing(true)}
        className="text-[10px] font-bold text-blue-600 hover:underline opacity-80 group-hover:opacity-100 transition"
        title="Hızlı Fiyat Güncelle"
      >
        ✏️
      </button>
    </div>
  );
}

"use client";

import { useState } from "react";
import toast from "react-hot-toast";

interface QuickStockUpdateProps {
  productId: string;
  currentStock: number;
  onUpdate?: () => void;
}

export default function QuickStockUpdate({ productId, currentStock, onUpdate }: QuickStockUpdateProps) {
  const [stock, setStock] = useState(currentStock);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleStockChange = async (newVal: number) => {
    if (newVal < 0) return;
    const toastId = toast.loading("Stok güncelleniyor...");
    setLoading(true);

    try {
      const res = await fetch("/api/admin/products/quick-update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "updateStock",
          productId,
          newStock: newVal,
        }),
      });

      if (res.ok) {
        setStock(newVal);
        setIsEditing(false);
        toast.success(`Stok ${newVal} olarak güncellendi!`, { id: toastId });
        if (onUpdate) onUpdate();
      } else {
        toast.error("Stok güncelleme başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası oluştu.", { id: toastId });
    } finally {
      setLoading(false);
    }
  };

  if (isEditing) {
    return (
      <div className="flex items-center gap-1 bg-white border border-blue-300 p-1 rounded-xl shadow-sm animate-in fade-in duration-200">
        <button
          disabled={loading || stock <= 0}
          onClick={() => handleStockChange(Math.max(0, stock - 5))}
          className="w-6 h-6 bg-red-100 text-red-700 hover:bg-red-200 rounded font-black text-xs transition"
          title="-5 Eksilt"
        >
          -5
        </button>
        <button
          disabled={loading || stock <= 0}
          onClick={() => handleStockChange(Math.max(0, stock - 1))}
          className="w-6 h-6 bg-orange-100 text-orange-700 hover:bg-orange-200 rounded font-black text-xs transition"
          title="-1 Eksilt"
        >
          -1
        </button>
        <input
          type="number"
          value={stock}
          onChange={(e) => setStock(Number(e.target.value))}
          className="w-12 text-center font-extrabold text-xs border border-gray-200 rounded p-1 outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button
          disabled={loading}
          onClick={() => handleStockChange(stock + 1)}
          className="w-6 h-6 bg-blue-100 text-blue-700 hover:bg-blue-200 rounded font-black text-xs transition"
          title="+1 Arttır"
        >
          +1
        </button>
        <button
          disabled={loading}
          onClick={() => handleStockChange(stock + 5)}
          className="w-6 h-6 bg-green-100 text-green-700 hover:bg-green-200 rounded font-black text-xs transition"
          title="+5 Arttır"
        >
          +5
        </button>
        <button
          disabled={loading}
          onClick={() => handleStockChange(stock)}
          className="px-2 py-1 bg-blue-600 hover:bg-blue-700 text-white rounded font-bold text-xs transition"
        >
          ✓ Kaydet
        </button>
        <button
          onClick={() => setIsEditing(false)}
          className="px-1.5 py-1 text-gray-400 hover:text-gray-600 font-bold text-xs"
        >
          ✕
        </button>
      </div>
    );
  }

  const stockBadgeClass =
    stock > 10
      ? "bg-green-50 text-green-700 border-green-200"
      : stock > 0
      ? "bg-amber-50 text-amber-700 border-amber-200"
      : "bg-red-50 text-red-700 border-red-200";

  return (
    <div className="flex items-center gap-1.5 group">
      <span className={`px-2.5 py-1 rounded-full text-xs font-black border ${stockBadgeClass}`}>
        {stock > 0 ? `${stock} Adet` : "Tükendi"}
      </span>
      <button
        onClick={() => setIsEditing(true)}
        className="text-[10px] font-bold text-blue-600 hover:underline opacity-80 group-hover:opacity-100 transition"
        title="Hızlı Stok Güncelle"
      >
        ✏️ Değiştir
      </button>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import toast from "react-hot-toast";
import CustomerDetailDrawer, { CustomerDetailDrawerData } from "./CustomerDetailDrawer";
import ConfirmModal from "@/components/ui/ConfirmModal";

export interface CustomerDTO {
  id: string;
  name: string;
  email: string;
  phone?: string | null;
  role: string;
  isActive: boolean;
  avatarUrl?: string | null;
  createdAt: string;
  ordersCount: number;
  returnsCount: number;
  exchangesCount: number;
  totalSpent: number;
  segment: { label: string; bg: string; text: string; icon: string };
  addresses: { id: string; title: string; city: string; district: string; address: string }[];
  recentOrders: { id: string; totalPrice: number; status: string; createdAt: string }[];
}

interface AdminUsersClientProps {
  users: CustomerDTO[];
  totalUsers: number;
  newUsers30d: number;
  avgSpent: number;
  vipUsersCount: number;
  passiveUsersCount: number;
  orderersCount: number;
}

export default function AdminUsersClient({
  users,
  totalUsers,
  newUsers30d,
  avgSpent,
  vipUsersCount,
  passiveUsersCount,
  orderersCount,
}: AdminUsersClientProps) {
  const router = useRouter();
  const searchParams = useSearchParams();

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedDrawerCustomer, setSelectedDrawerCustomer] = useState<CustomerDetailDrawerData | null>(null);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [isBulkDeleteModalOpen, setIsBulkDeleteModalOpen] = useState(false);
  const [isPending, startTransition] = useTransition();

  // URL Parametreleri
  const searchQuery = searchParams.get("q") || "";
  const roleFilter = searchParams.get("role") || "";
  const statusFilter = searchParams.get("status") || "";
  const segmentFilter = searchParams.get("segment") || "";
  const pageSize = Number(searchParams.get("limit")) || 10;
  const currentPage = Number(searchParams.get("page")) || 1;

  const [searchInput, setSearchInput] = useState(searchQuery);

  const updateFilters = (newParams: Record<string, string | number | null>) => {
    const params = new URLSearchParams(searchParams.toString());
    Object.entries(newParams).forEach(([key, value]) => {
      if (value === null || value === "") {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    startTransition(() => {
      router.push(`/admin/users?${params.toString()}`);
    });
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateFilters({ q: searchInput, page: 1 });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(users.map((u) => u.id));
    } else {
      setSelectedIds([]);
    }
  };

  const toggleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleBulkAction = async (action: string) => {
    if (selectedIds.length === 0) return;

    if (action === "delete") {
      setIsBulkDeleteModalOpen(true);
      return;
    }

    await executeBulkAction(action);
  };

  const executeBulkAction = async (action: string) => {
    const toastId = toast.loading(`${selectedIds.length} kullanıcı işleniyor...`);
    try {
      const res = await fetch("/api/admin/users/bulk", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userIds: selectedIds, action }),
      });

      if (res.ok) {
        toast.success("Toplu işlem başarıyla uygulandı!", { id: toastId });
        setSelectedIds([]);
        router.refresh();
      } else {
        toast.error("Toplu işlem başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  };

  const handleToggleUserActive = async (userId: string, currentActive: boolean) => {
    const toastId = toast.loading("Kullanıcı durumu güncelleniyor...");
    try {
      const res = await fetch(`/api/admin/users/${userId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: !currentActive }),
      });

      if (res.ok) {
        toast.success("Kullanıcı durumu başarıyla güncellendi!", { id: toastId });
        router.refresh();
      } else {
        toast.error("Güncelleme başarısız.", { id: toastId });
      }
    } catch (error) {
      toast.error("Sunucu hatası.", { id: toastId });
    }
  };

  const openDrawer = (customer: CustomerDTO) => {
    setSelectedDrawerCustomer(customer);
    setIsDrawerOpen(true);
  };

  const totalPages = Math.ceil(users.length / pageSize) || 1;
  const paginatedUsers = users.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return (
    <div className="space-y-6 w-full animate-in fade-in duration-300">

      {/* 🚀 BAŞLIK VE AKSİYONLAR */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-200 pb-5">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
            <span>👥</span> Müşteri Yönetim Merkezi (CRM)
          </h1>
          <p className="text-gray-500 text-xs sm:text-sm mt-0.5 font-medium">
            Müşteri veritabanı, sipariş geçmişi, harcama segmentleri ve profil yönetimi.
          </p>
        </div>

        {selectedIds.length > 0 && (
          <div className="flex items-center gap-2 bg-blue-50 border border-blue-200 p-2 rounded-2xl shadow-xs animate-in zoom-in duration-200">
            <span className="text-xs font-black text-blue-900 px-2">{selectedIds.length} Seçildi:</span>
            <button
              onClick={() => handleBulkAction("activate")}
              className="bg-green-600 hover:bg-green-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs"
            >
              🟢 Aktifleştir
            </button>
            <button
              onClick={() => handleBulkAction("deactivate")}
              className="bg-amber-600 hover:bg-amber-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs"
            >
              🔴 Pasifleştir
            </button>
            <button
              onClick={() => handleBulkAction("delete")}
              className="bg-red-600 hover:bg-red-700 text-white font-extrabold px-3 py-1.5 rounded-xl text-xs transition shadow-xs"
            >
              🗑 Sil
            </button>
          </div>
        )}
      </div>

      {/* 🚀 1. ÖZET İSTATİSTİK 6 METRİK KARTI */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 sm:gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-blue-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Toplam Müşteri</span>
          <p className="text-xl sm:text-2xl font-black text-gray-900">{totalUsers}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-emerald-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Yeni Üye (30 Gün)</span>
          <p className="text-xl sm:text-2xl font-black text-emerald-600">{newUsers30d}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-indigo-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Ort. Harcama</span>
          <p className="text-xl sm:text-2xl font-black text-indigo-600">{avgSpent.toLocaleString("tr-TR")} ₺</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-amber-500">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">VIP Müşteriler</span>
          <p className="text-xl sm:text-2xl font-black text-amber-600">{vipUsersCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-purple-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Sipariş Veren</span>
          <p className="text-xl sm:text-2xl font-black text-purple-600">{orderersCount}</p>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 border-l-4 border-l-red-600">
          <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest block mb-0.5">Pasif Hesaplar</span>
          <p className="text-xl sm:text-2xl font-black text-red-600">{passiveUsersCount}</p>
        </div>
      </div>

      {/* 🚀 2. GELİŞMİŞ FİLTRELEME VE GLOBAL ARAMA BAR */}
      <div className="bg-white p-4 rounded-2xl shadow-xs border border-gray-200 space-y-3">
        <form onSubmit={handleSearchSubmit} className="flex flex-col lg:flex-row gap-3 items-stretch lg:items-center">

          {/* Global Arama Kutu */}
          <div className="flex-1 relative">
            <span className="absolute left-3.5 top-3 text-gray-400 text-sm">🔍</span>
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="Ad Soyad, Email veya Telefon arayın..."
              className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-xs sm:text-sm min-h-[44px]"
            />
          </div>

          {/* Rol Filtresi */}
          <select
            value={roleFilter}
            onChange={(e) => updateFilters({ role: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Roller</option>
            <option value="USER">👤 Müşteri (USER)</option>
            <option value="ADMIN">🛡️ Yönetici (ADMIN)</option>
          </select>

          {/* Durum Filtresi */}
          <select
            value={statusFilter}
            onChange={(e) => updateFilters({ status: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Durumlar</option>
            <option value="active">🟢 Aktif Hesaplar</option>
            <option value="passive">🔴 Pasif / Engelli</option>
          </select>

          {/* Segment Filtresi */}
          <select
            value={segmentFilter}
            onChange={(e) => updateFilters({ segment: e.target.value, page: 1 })}
            className="px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-xs sm:text-sm min-h-[44px] font-medium"
          >
            <option value="">Tüm Segmentler</option>
            <option value="vip">🏆 VIP Müşteriler</option>
            <option value="loyal">💎 Sadık Müşteriler</option>
            <option value="new">🆕 Yeni Üyeler</option>
            <option value="zero">🎯 İlk Sipariş Bekleyen</option>
          </select>

          <button
            type="submit"
            className="bg-gray-900 hover:bg-gray-800 text-white font-extrabold px-5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
          >
            Filtrele
          </button>

          {(searchQuery || roleFilter || statusFilter || segmentFilter) && (
            <button
              type="button"
              onClick={() => {
                setSearchInput("");
                startTransition(() => router.push("/admin/users"));
              }}
              className="text-red-600 hover:bg-red-50 border border-red-200 font-extrabold px-3.5 py-2.5 rounded-xl transition text-xs sm:text-sm min-h-[44px]"
            >
              Filtreleri Sıfırla
            </button>
          )}
        </form>
      </div>

      {/* 🚀 3. MODERN DATA TABLE (DESKTOP) VE KART DÜZENİ (MOBİL) */}
      <div className="bg-white rounded-2xl shadow-xs border border-gray-200 overflow-hidden">

        {/* ÜST TOPLU SEÇİM VE GÖSTERİM BARI */}
        <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
          <label className="flex items-center gap-2 text-xs font-bold text-gray-700 cursor-pointer">
            <input
