"use client";

import { useState, useEffect } from "react";
import Image from "next/image";
import { useCartStore } from "@/lib/store";
import toast from "react-hot-toast";

interface SavedItem {
  id: string;
  name: string;
  price: number;
  imageUrl: string;
}

export default function SaveForLaterSection() {
  const [savedItems, setSavedItems] = useState<SavedItem[]>([]);
  const addItem = useCartStore((state) => state.addItem);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("vitrin_saved_for_later");
      if (saved) {
        Promise.resolve().then(() => setSavedItems(JSON.parse(saved)));
      }
    } catch (e) {}
  }, []);

  const moveToCart = (item: SavedItem) => {
    addItem({
      id: item.id,
      name: item.name,
      price: item.price,
      imageUrls: [item.imageUrl],
      quantity: 1,
    });
    const updated = savedItems.filter((i) => i.id !== item.id);
    setSavedItems(updated);
    localStorage.setItem("vitrin_saved_for_later", JSON.stringify(updated));
    toast.success(`${item.name} sepetinize geri eklendi! 🛒`);
  };

  const removeSavedItem = (id: string) => {
    const updated = savedItems.filter((i) => i.id !== id);
    setSavedItems(updated);
    localStorage.setItem("vitrin_saved_for_later", JSON.stringify(updated));
    toast.success("Ürün listenizden kaldırıldı.");
  };

  if (savedItems.length === 0) return null;

  return (
    <div className="bg-white p-6 rounded-3xl border border-gray-200 shadow-xs space-y-4 text-left my-6">
      <div className="flex justify-between items-center">
        <h3 className="font-black text-gray-900 text-base flex items-center gap-2">
          <span>🕒</span> Daha Sonra Satın Alınacaklar ({savedItems.length})
        </h3>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {savedItems.map((item) => (
          <div key={item.id} className="p-3 bg-gray-50 rounded-2xl border border-gray-200 flex items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-white rounded-xl border border-gray-100 p-1 flex-shrink-0 flex items-center justify-center">
                {item.imageUrl ? <Image src={item.imageUrl} alt={item.name} width={48} height={48} className="object-contain" /> : <span>📦</span>}
              </div>
              <div>
                <p className="font-bold text-gray-900 text-xs line-clamp-1">{item.name}</p>
                <span className="font-black text-blue-600 text-xs">{item.price.toLocaleString("tr-TR")} ₺</span>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => moveToCart(item)}
                className="bg-blue-600 hover:bg-blue-700 text-white text-xs font-extrabold px-3 py-1.5 rounded-xl transition shadow-xs"
              >
                Sepete Ekle
              </button>
              <button
                onClick={() => removeSavedItem(item.id)}
                className="text-gray-400 hover:text-red-600 text-xs font-bold p-1"
                aria-label={`${item.name} ürününü listeden kaldır`}
                title={`${item.name} ürününü listeden kaldır`}
              >
                ✕
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import ProductCard, { ProductCardProps } from "@/components/ProductCard";

export default function RecentlyViewedProducts({ currentProduct }: { currentProduct?: ProductCardProps }) {
  const [recentlyViewed, setRecentlyViewed] = useState<ProductCardProps[]>([]);
  const sliderRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
      const existing = localStorage.getItem("vitrin_recently_viewed");
      let list: ProductCardProps[] = existing ? JSON.parse(existing) : [];

      if (currentProduct) {
        // Tekrarlayanları temizle ve en başa ekle
        list = [currentProduct, ...list.filter((item) => item.id !== currentProduct.id)].slice(0, 10);
        localStorage.setItem("vitrin_recently_viewed", JSON.stringify(list));
      }

      // Mevcut ürünü listede tekrar göstermemek için filtrele
      const filtered = list.filter((item) => item.id !== currentProduct?.id);
      Promise.resolve().then(() => setRecentlyViewed(filtered));
    } catch (e) {}
  }, [currentProduct]);

  const scrollLeft = () => {
    if (sliderRef.current) {
      sliderRef.current.scrollBy({ left: -320, behavior: "smooth" });
    }
  };

  const scrollRight = () => {
    if (sliderRef.current) {
      sliderRef.current.scrollBy({ left: 320, behavior: "smooth" });
    }
  };

  if (recentlyViewed.length === 0) return null;

  return (
    <section className="bg-gray-50/70 p-6 sm:p-10 rounded-3xl border border-gray-200/80 shadow-2xs space-y-6 my-8 text-left relative group">
      {/* BAŞLIK VE OK BUTONLARI */}
      <div className="flex justify-between items-end border-b border-gray-200/80 pb-4">
        <div>
          <span className="bg-purple-100 text-purple-800 text-[10px] font-black uppercase px-2.5 py-0.5 rounded-full">
            🕒 GEÇMİŞİNİZ
          </span>
          <h3 className="text-xl sm:text-2xl font-black text-gray-900 tracking-tight mt-1">Son İnceledikleriniz</h3>
          <p className="text-xs sm:text-sm text-gray-500 font-medium mt-0.5">
            Daha önce göz attığınız ve karşılaştırmak isteyebileceğiniz ürünler.
          </p>
        </div>

        {/* OK BUTONLARI */}
        <div className="hidden sm:flex items-center gap-2">
          <button
            onClick={scrollLeft}
            className="w-10 h-10 rounded-full bg-white hover:bg-purple-600 hover:text-white text-gray-600 transition flex items-center justify-center font-black shadow-2xs border border-gray-200"
            aria-label="Önceki"
          >
            ←
          </button>
          <button
            onClick={scrollRight}
            className="w-10 h-10 rounded-full bg-white hover:bg-purple-600 hover:text-white text-gray-600 transition flex items-center justify-center font-black shadow-2xs border border-gray-200"
            aria-label="Sonraki"
          >
            →
          </button>
        </div>
      </div>

      {/* KAYAR LİSTE (RESPONSIVE SLIDER) */}
      <div
        ref={sliderRef}
        className="flex gap-4 sm:gap-6 overflow-x-auto snap-x snap-mandatory py-2 custom-scrollbar hide-scrollbar-on-mobile -mx-2 px-2"
        style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
      >
        {recentlyViewed.map((product) => (
          <div
            key={product.id}
            className="snap-start shrink-0 w-[82vw] sm:w-[260px] md:w-[280px] lg:w-[270px] text-gray-900"
          >
            <ProductCard product={product} />
          </div>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useUser, SignOutButton, useClerk } from "@clerk/nextjs";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

interface AccountPopoverProps {
  onClose?: () => void;
}

interface UserProfileResponse {
  name?: string;
  email?: string;
  avatarUrl?: string;
  _count?: {
    orders?: number;
    returns?: number;
    exchanges?: number;
  };
}

export default function AccountPopover({ onClose }: AccountPopoverProps) {
  const { user } = useUser();
  const { openUserProfile } = useClerk();
  const router = useRouter();

  const [profileData, setProfileData] = useState<UserProfileResponse | null>(null);

  useEffect(() => {
    fetch("/api/profile")
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => {
        if (data?.user) {
          setProfileData(data.user);
        }
      })
      .catch(() => {});
  }, []);

  const displayName =
    profileData?.name ||
    user?.fullName ||
    user?.firstName ||
    "Değerli Müşterimiz";

  const displayEmail =
    profileData?.email ||
    user?.primaryEmailAddress?.emailAddress ||
    "";

  const displayAvatar =
    profileData?.avatarUrl || user?.imageUrl || "";

  const ordersCount = profileData?._count?.orders ?? 0;
  const returnsCount = (profileData?._count?.returns ?? 0) + (profileData?._count?.exchanges ?? 0);

  const handleEditProfile = () => {
    onClose?.();
    if (typeof openUserProfile === "function") {
      try {
        openUserProfile();
        return;
      } catch (e) {}
    }
    router.push("/profile?tab=settings");
  };

  return (
    <div
      role="dialog"
      aria-label="Kullanıcı Menüsü"
      className="absolute right-0 top-full mt-2 w-72 sm:w-80 bg-white shadow-2xl rounded-2xl border border-gray-100 z-50 animate-in fade-in slide-in-from-top-2 duration-200 p-4 text-xs sm:text-sm text-gray-800"
    >
      {/* a) ÜST KULLANICI BİLGİ ALANI */}
      <div className="flex items-center justify-between pb-3 border-b border-gray-100">
        <div className="flex items-center gap-3 min-w-0">
          <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 border border-blue-200 overflow-hidden flex-shrink-0 flex items-center justify-center font-bold text-base">
            {displayAvatar ? (
              <Image
                src={displayAvatar}
                alt={displayName}
                width={40}
                height={40}
                className="object-cover w-full h-full"
              />
            ) : (
              <span>{displayName.charAt(0).toUpperCase()}</span>
            )}
          </div>
          <div className="min-w-0">
            <p className="font-extrabold text-gray-900 text-sm truncate">{displayName}</p>
            <p className="text-[11px] text-gray-400 font-medium truncate">{displayEmail}</p>
          </div>
        </div>

        <button
          type="button"
          onClick={handleEditProfile}
          className="p-1.5 rounded-lg text-gray-400 hover:text-blue-600 hover:bg-gray-100 transition-colors flex-shrink-0 cursor-pointer"
          title="Profili Düzenle"
          aria-label="Profili Düzenle"
